1	import { test } from 'node:test';
2	import assert from 'node:assert/strict';
3	import { spawnSync } from 'node:child_process';
4	import { mkdtempSync, mkdirSync, writeFileSync } from 'node:fs';
5	import { tmpdir } from 'node:os';
6	import { join, dirname } from 'node:path';
7	import { fileURLToPath } from 'node:url';
8	import { makeTranscript } from './helpers.mjs';
9	import { removeTree } from '../engine/remove-tree.mjs';
10	
11	const GUARD = join(dirname(fileURLToPath(import.meta.url)), '..', 'engine', 'hooks', 'pretooluse-command.mjs');
12	
13	function runGuard(payload, env = {}) {
14	  return spawnSync(process.execPath, [GUARD], { input: JSON.stringify(payload), encoding: 'utf8', env: { ...process.env, ...env } });
15	}
16	
17	const bash = (command) => ({ tool_name: 'Bash', tool_input: { command } });
18	
19	test('blocks remote-branch deletion in both forms', () => {
20	  for (const cmd of [
21	    'git push origin --delete feature-x',
22	    'git push -d origin feature-x',
23	    'git push origin :feature-x',
24	  ]) {
25	    const r = runGuard(bash(cmd));
26	    assert.equal(r.status, 2, cmd);
27	    assert.match(r.stderr, /never delete a remote branch/);
28	  }
29	});
30	
31	test('allows ordinary pushes and non-Bash tools', () => {
32	  for (const payload of [
33	    bash('git push -u origin feature-x'),
34	    bash('git push --force-with-lease origin feature-x'),
35	    bash('git push origin main:refs/heads/main'),
36	    { tool_name: 'Edit', tool_input: {} },
37	  ]) {
38	    assert.equal(runGuard(payload).status, 0, JSON.stringify(payload));
39	  }
40	});
41	
42	// --- path-scoped skills ---------------------------------------------------------
43	
44	// A project declaring one local pack whose skill forces itself for product-wiki/**.
45	function scopedRepo() {
46	  const root = mkdtempSync(join(tmpdir(), 'claudinite-guard-'));
47	  const pack = join(root, '.claudinite', 'local', 'packs', 'demo');
48	  mkdirSync(join(pack, 'skills', 'writing-wiki-pages'), { recursive: true });
49	  writeFileSync(join(pack, 'pack.mjs'), `export default {
50	  ruleRoutingGuidance: { belongs: 'demo', excludes: 'nothing' },
51	};
52	`);
53	  writeFileSync(join(pack, 'skills', 'writing-wiki-pages', 'SKILL.md'), '---\nname: writing-wiki-pages\ndescription: demo\nmetadata:\n  force-load-on-file-edits-paths:\n    - "product-wiki/**"\n---\n');
54	  writeFileSync(join(root, '.claudinite-settings.json'), JSON.stringify({ packs: ['local/demo'] }));
55	  return root;
56	}
57	
58	const skillLoad = (skill) => ({ type: 'assistant', message: { content: [{ type: 'tool_use', name: 'Skill', input: { skill } }] } });
59	const edit = (root, file_path, transcript_path) => ({ tool_name: 'Edit', tool_input: { file_path: join(root, file_path) }, transcript_path });
60	
61	test('a file tool on a scoped path is blocked until the skill is loaded, then allowed', () => {
62	  const root = scopedRepo();
63	  const bare = makeTranscript([{ type: 'user', message: { content: 'go' } }]);
64	  const loaded = makeTranscript([skillLoad('writing-wiki-pages')]);
65	  try {
66	    const blocked = runGuard(edit(root, 'product-wiki/Market/README.md', bare.path), { CLAUDE_PROJECT_DIR: root });
67	    assert.equal(blocked.status, 2, blocked.stderr);
68	    assert.match(blocked.stderr, /product-wiki\/Market\/README\.md is edited only with the `writing-wiki-pages` skill loaded/);
69	    assert.match(blocked.stderr, /skill: "writing-wiki-pages"/);
70	
71	    assert.match(blocked.stderr, /or Read \.claudinite\/local\/packs\/demo\/skills\/writing-wiki-pages\/SKILL\.md/);
72	
73	    const allowed = runGuard(edit(root, 'product-wiki/Market/README.md', loaded.path), { CLAUDE_PROJECT_DIR: root });
74	    assert.equal(allowed.status, 0, allowed.stderr);
75	    const readLoaded = makeTranscript([{ type: 'assistant', message: { content: [{ type: 'tool_use', name: 'Read', input: { file_path: join(root, '.claude/skills/writing-wiki-pages/SKILL.md') } }] } }]);
76	    try {
77	      assert.equal(runGuard(edit(root, 'product-wiki/Market/README.md', readLoaded.path), { CLAUDE_PROJECT_DIR: root }).status, 0, 'a Read of the SKILL.md is a load');
78	    } finally { readLoaded.cleanup(); }
79	
80	    // Write and NotebookEdit name their file the same way; a path outside every
81	    // pattern, and one outside the project, are never the guard's business.
82	    const write = runGuard({ tool_name: 'Write', tool_input: { file_path: join(root, 'product-wiki/README.md') }, transcript_path: bare.path }, { CLAUDE_PROJECT_DIR: root });
83	    assert.equal(write.status, 2, write.stderr);
84	    const notebook = runGuard({ tool_name: 'NotebookEdit', tool_input: { notebook_path: join(root, 'product-wiki/x.ipynb') }, transcript_path: bare.path }, { CLAUDE_PROJECT_DIR: root });
85	    assert.equal(notebook.status, 2, notebook.stderr);
86	    assert.equal(runGuard(edit(root, 'src/app.mjs', bare.path), { CLAUDE_PROJECT_DIR: root }).status, 0);
87	    assert.equal(runGuard({ tool_name: 'Edit', tool_input: { file_path: '/elsewhere/product-wiki/README.md' }, transcript_path: bare.path }, { CLAUDE_PROJECT_DIR: root }).status, 0);
88	  } finally {
89	    bare.cleanup(); loaded.cleanup(); removeTree(root);
90	  }
91	});
92	
93	test('a subagent that loaded the skill in its own stream is not blocked', () => {
94	  const root = scopedRepo();
95	  // The payload names the session file whatever agent is calling (#1735), so a
96	  // load a subagent made is visible only in its own `subagents/` stream.
97	  const delegated = makeTranscript(
98	    [{ type: 'user', message: { content: 'go' } }],
99	    { abc123: [skillLoad('writing-wiki-pages')] },
100	  );
101	  const unrelated = makeTranscript(
102	    [{ type: 'user', message: { content: 'go' } }],
103	    { abc123: [skillLoad('some-other-skill')] },
104	  );
105	  try {
106	    const allowed = runGuard(edit(root, 'product-wiki/Market/README.md', delegated.path), { CLAUDE_PROJECT_DIR: root });
107	    assert.equal(allowed.status, 0, allowed.stderr);
108	    const blocked = runGuard(edit(root, 'product-wiki/Market/README.md', unrelated.path), { CLAUDE_PROJECT_DIR: root });
109	    assert.equal(blocked.status, 2, 'a subagent stream that loaded some other skill still blocks');
110	  } finally {
111	    delegated.cleanup(); unrelated.cleanup(); removeTree(root);
112	  }
113	});
114	
115	test('a project declaring no scoped skill, or one with no transcript, lets every edit through', () => {
116	  const root = mkdtempSync(join(tmpdir(), 'claudinite-guard-'));
117	  try {
118	    writeFileSync(join(root, '.claudinite-settings.json'), JSON.stringify({ packs: ['basics'] }));
119	    assert.equal(runGuard(edit(root, 'product-wiki/README.md', '/nonexistent.jsonl'), { CLAUDE_PROJECT_DIR: root }).status, 0);
120	  } finally { removeTree(root); }
121	});
122

