383	          what: `"taskScheduler.disabledTasks" must be an array of "<pack>/<task>" ids, got ${JSON.stringify(disabledTasks)}`,
384	          fix: 'list the tasks this repo does not run, e.g. ["claudinite-lifecycle/update"]',
385	        });
386	      }
387	
388	      const { dispatch } = raw.taskScheduler;
389	      const endpoints = raw.taskScheduler[ENDPOINTS_KEY] ?? raw.taskScheduler[LEGACY_ENDPOINTS_KEY];
390	      if (dispatch !== undefined && !DISPATCH_MODES.includes(dispatch)) {
391	        errors.push({
392	          what: `"taskScheduler.dispatch" must be one of ${DISPATCH_MODES.join(', ')}, got ${JSON.stringify(dispatch)}`,
393	          fix: 'omit the key — the work-item queue is the only dispatch mechanism; "slots" named the slot scheduler, which is deleted',
394	        });
395	      }
396	      // The endpoint map (tasks-dispatch DESIGN §12): a name → { url, tokenSecret }.
397	      // `tokenSecret` is the NAME of a repo Actions secret and never a value —
398	      // that indirection is the whole reason a task may declare an endpoint at all,
399	      // since a task declaration is vendored verbatim into every consuming repo.
400	      if (endpoints !== undefined) {
401	        if (endpoints === null || typeof endpoints !== 'object' || Array.isArray(endpoints)) {
402	          errors.push({ what: `"taskScheduler.${ENDPOINTS_KEY}" must be an object of endpoint name → { url, tokenSecret }`, fix: 'e.g. { "default": { "url": "https://…", "tokenSecret": "CCR_SESSION_TOKEN" } }' });
403	        } else {
404	          for (const [epName, entry] of Object.entries(endpoints)) {
405	            if (entry === null || typeof entry !== 'object' || Array.isArray(entry)
406	                || typeof entry.url !== 'string' || typeof entry.tokenSecret !== 'string') {
407	              errors.push({ what: `"taskScheduler.${ENDPOINTS_KEY}.${epName}" must be { url, tokenSecret } (both strings)`, fix: 'give the endpoint an invocation URL and the NAME of the repo Actions secret holding its token — never the token itself' });
408	            }
409	          }
410	        }
411	      }
412	      taskScheduler = raw.taskScheduler;
413	    }
414	  }
415	
416	  // --- the installed mount: the engine version this repo holds, and the version of
417	  // each pack it has installed. The current home is the top-level `engineVersion`
418	  // and each pack entry's own `version`; the retired `claudinite` block is read
419	  // underneath for a member the #1252 record has not reached, and a pack renamed
420	  // since that block was written still keys its version under the old spelling, so
421	  // the legacy map is canonicalized before anything compares it.
422	  let engineVersion = null;
423	  if (raw.engineVersion !== undefined) {
424	    if (isVersion(raw.engineVersion)) engineVersion = raw.engineVersion;
425	    else {
426	      errors.push({
427	        what: `"engineVersion" must be a version — date-anchored <day>.<n>, got ${JSON.stringify(raw.engineVersion)}`,
428	        fix: 'leave it to the update flows, which write the version they installed',
429	      });
430	    }
431	  } else if (isVersion(raw.claudinite?.engineVersion)) {
432	    engineVersion = raw.claudinite.engineVersion;
433	  }
434	
435	  const packVersions = {};
436	  const legacyVersions = raw.claudinite?.packVersions;
437	  if (legacyVersions && typeof legacyVersions === 'object' && !Array.isArray(legacyVersions)) {
438	    Object.assign(packVersions, canonicalPackVersions(legacyVersions));
439	  }
440	  for (const entry of packEntries) {
441	    if (entry.version !== undefined) packVersions[entry.id] = entry.version;
442	  }
443	
444	  // --- the delivery override. `true` is the only value that means anything, so
445	  // anything else present is a typo the run must not read as "yes" or silently as
446	  // "no" — a wrong answer here is a PR merged unreviewed on a repo that asked for
447	  // review, or a repo's daily update stalled forever waiting for a human nobody
448	  // told. The retired `maintenance.delivery` says the same thing the old way, and
449	  // an unrecognised value THERE is equally an error rather than a default.
450	  let requirePrReview = false;
451	  if (raw.dailyClaudiniteUpdatesRequirePrReview !== undefined) {
452	    if (typeof raw.dailyClaudiniteUpdatesRequirePrReview === 'boolean') {
453	      requirePrReview = raw.dailyClaudiniteUpdatesRequirePrReview;
454	    } else {
455	      errors.push({
456	        what: `"dailyClaudiniteUpdatesRequirePrReview" must be true or false, got ${JSON.stringify(raw.dailyClaudiniteUpdatesRequirePrReview)}`,
457	        fix: 'set it to true to leave this repo\'s update PR for a human, or remove the key',
458	      });
459	    }
460	  } else if (raw.maintenance?.delivery !== undefined) {
461	    const legacy = String(raw.maintenance.delivery).trim();
462	    if (['review', 'pr'].includes(legacy)) requirePrReview = true;
463	    else if (!['auto-merge', 'auto', 'push', ''].includes(legacy)) {
464	      errors.push({
465	        what: `the retired "maintenance.delivery" holds ${JSON.stringify(raw.maintenance.delivery)}, which is neither auto-merge nor review`,
466	        fix: 'remove the "maintenance" block — set "dailyClaudiniteUpdatesRequirePrReview": true if this repo\'s update PR must wait for a human',
467	      });
468	    }
469	  }
470	
471	  // --- dormant: a plain boolean, validated as one. A string "true", a `{ since }`
472	  // object or a reason left in its place would all read as dormant to a truthiness
473	  // test and as active to this one, and the difference is a whole repo's scheduled
474	  // work — so the wrong TYPE is a settings error, not a value to coerce.
475	  if (raw.dormant !== undefined && typeof raw.dormant !== 'boolean') {
476	    errors.push({
477	      what: `"dormant" must be true or false, got ${JSON.stringify(raw.dormant)}`,
478	      fix: 'set "dormant": true to stop this project\'s recurring work, or remove the key',
479	    });
480	  }
481	
482	  return {
483	    packs,
484	    packEntries,
485	    rules,
486	    accept,
487	    sharedConstants: Array.isArray(raw.sharedConstants) ? raw.sharedConstants : [],
488	    packConfig,
489	    taskScheduler,
490	    // The installed mount, normalized from wherever this member happens to spell
491	    // it: the top-level `engineVersion` and each entry's own `version`, falling
492	    // back to the retired `claudinite` block for a member that has not run the
493	    // #1252 record yet. Downstream reads ONE shape and never learns there were
494	    // two — and omitting a declared key from this returned shape is the worst
495	    // kind of bug, legal to write and impossible to read: it is what made the
496	    // stamp invisible to the scheduler and silently killed baselining fleet-wide,
497	    // every repo self-skipping as "no vendored mount" while its runs went green.
498	    // The CONFIG_KEYS-survive-loadConfig test pins the whole set.
499	    engineVersion,
500	    packVersions,
501	    // The harsh override, normalized to the boolean every caller asks for and named
502	    // exactly as the file names it — one spelling, so nothing has to learn that the
503	    // key and the field it loads into are different words. Absent is the normal
504	    // shape and means the update PR lands on its own; the retired
505	    // `maintenance.delivery: review` says the same thing the old way.
506	    dailyClaudiniteUpdatesRequirePrReview: requirePrReview,
507	    // Normalized to a boolean rather than passed through: everything downstream
508	    // asks "is this project dormant", and a tri-state (true / false / absent) would
509	    // invite each caller to answer the absent case for itself. Absent is active.
510	    dormant: isDormant(raw),
511	    errors,
512	  };
513	}
514	
515	export function buildContext({ root, mode = 'changed', baseOverride = null, transcriptPath = null }) {
516	  root = resolve(root);
517	  const baseRef = baseOverride || resolveBaseRef(root);
518	  refreshBaseRef(root, baseRef);
519	  const mergeBase = baseRef ? (gitTry(root, 'merge-base', 'HEAD', baseRef) || '').trim() || null : null;
520	  // Diffing against HEAD keeps uncommitted work in scope even when no base branch resolves.
521	  const diffBase = mergeBase || 'HEAD';
522	  // Is this commit already on the base branch? `--is-ancestor` exits non-zero for "no",
523	  // which gitTry surfaces as null. No base ref to compare against ⇒ nothing is known to
524	  // be on it, so nothing is filtered out.
525	  const onBaseBranch = (sha) =>
526	    !!baseRef && gitTry(root, 'merge-base', '--is-ancestor', sha, baseRef) !== null;
527	
528	  const tracked = lines(gitTry(root, 'ls-files'));
529	  const untracked = lines(gitTry(root, 'ls-files', '--others', '--exclude-standard'));
530	
531	  const vsBase = lines(gitTry(root, 'diff', '--name-only', '--diff-filter=d', diffBase));
532	  let scanned;
533	  if (mode === 'all') {
534	    scanned = [...tracked, ...untracked];
535	  } else {
536	    scanned = [...new Set([...vsBase, ...untracked])];
537	  }
538	  // The vendored corpus under the shared mount is canon-owned, never the
539	  // project's own code — structurally out of scope for every check, on any git
540	  // host and any checkout (deliberately not attribute-driven). The consumer's
541	  // own .claudinite/local/packs/ sits BESIDE the shared mount and stays fully
542	  // in scope.
543	  // git emits '/'-separated paths on every platform; SHARED_SUBDIR is joined
544	  // with the platform separator, so normalize before prefix-matching.
545	  const sharedPrefix = `${SHARED_SUBDIR.split(sep).join('/')}/`;
546	  scanned = scanned.filter((f) => !f.startsWith(sharedPrefix));
547	  // Every in-scope regular file, vendored/generated included.
548	  const allFiles = scanned.filter((f) => existsSync(join(root, f)) && statSync(join(root, f)).isFile());
549	  // The default sweep excludes vendored/generated files, so `ctx.files` is the
550	  // project's OWN authored code and every check skips them for free (see vendoredSet).
551	  const vendored = vendoredSet(root, allFiles);
552	  const files = allFiles.filter((f) => !vendored.has(f));
553	  // The in-scope files the current change touched (vs the scoping base),
554	  // untracked included — the file set behind lines.mjs addedLines, for
555	  // check-the-work rules that judge the work rather than re-audit the world.
556	  const changedSet = new Set([...vsBase, ...untracked]);
557	  const changedFiles = files.filter((f) => changedSet.has(f));
558	
559	  const deleted = mergeBase ? lines(gitTry(root, 'diff', '--name-only', '--diff-filter=D', mergeBase)) : [];
560	
561	  let commits = [];
562	  if (mergeBase) {
563	    const out = gitTry(root, 'log', '--format=%s%n%b%x00', `${mergeBase}..HEAD`);
564	    commits = (out || '').split('\0').map((m) => m.trim()).filter(Boolean);
565	  }
566	
567	  const branch = (gitTry(root, 'rev-parse', '--abbrev-ref', 'HEAD') || '').trim();
568	
569	  // Conversation surface: the Stop hook forwards the session's transcript_path;
570	  // every other surface (CI, a manual run) has none, and conversation rules must
571	  // return [] when this is null. Parsed lazily and cached — most sweeps never ask.
572	  let conversationCache;
573	  let sessionEntriesCache;
574	
575	  // Checks are read-only over an immutable snapshot of the tree, so file and
576	  // base-blob reads are cached for the sweep: many rules re-read the same files,
577	  // and each readBase is otherwise a git subprocess.
578	  const readCache = new Map();
579	  const readBaseCache = new Map();
580	
581	  return {
582	    root,
583	    mode,
584	    baseRef,
585	    mergeBase,
586	    files,
587	    allFiles,
588	    changedFiles,
589	    tracked,
590	    untracked,
591	    deleted,
592	    commits,
593	    branch,
594	    config: loadConfig(root),
595	
596	    exists: (path) => existsSync(join(root, path)),
597	    read(path) {
598	      if (!readCache.has(path)) {
599	        let text;
600	        try { text = readFileSync(join(root, path), 'utf8'); } catch { text = null; }
601	        readCache.set(path, text);
602	      }
603	      return readCache.get(path);
604	    },
605	
606	    // File content at the scoping base (the merge-base with the base branch), or
607	    // null if the file didn't exist there or no base resolves. Lets a delta
608	    // check compare structured state — e.g. a manifest's permission set — against
609	    // the baseline precisely, immune to text-diff line noise (JSON trailing
610	    // commas make appending an array element re-touch the previous line).
611	    readBase(path) {
612	      if (!mergeBase) return null;
613	      if (!readBaseCache.has(path)) readBaseCache.set(path, gitTry(root, 'show', `${mergeBase}:${path}`));
614	      return readBaseCache.get(path);
615	    },
616	
617	    // Added lines of one file relative to the scoping base (untracked file = every line).
618	    addedLines(file) {
619	      if (!tracked.includes(file)) {
620	        const text = this.read(file);
621	        return text === null ? [] : text.split('\n').map((t, i) => ({ line: i + 1, text: t }));
622	      }
623	      const out = gitTry(root, 'diff', '-U0', diffBase, '--', file);
624	      const added = [];
625	      let lineNo = 0;
626	      for (const l of (out || '').split('\n')) {
627	        const hunk = /^@@ -\d+(?:,\d+)? \+(\d+)(?:,\d+)? @@/.exec(l);
628	        if (hunk) { lineNo = Number(hunk[1]); continue; }
629	        if (l.startsWith('+') && !l.startsWith('+++')) { added.push({ line: lineNo, text: l.slice(1) }); lineNo += 1; }
630	        else if (!l.startsWith('-')) lineNo += l ? 1 : 0;
631	      }
632	      return added;
633	    },
634	
635	    // Parsed transcript entries of the session driving this run, or null when no
636	    // transcript is available (see conversationCache above).
637	    // The lines the change REMOVES from a tracked file, numbered as the base
638	    // had them — the diff's "-" side, the mirror of addedLines. A file the
639	    // base did not hold removed nothing.
640	    removedLines(file) {
641	      if (!mergeBase || !tracked.includes(file)) return [];
642	      const out = gitTry(root, 'diff', '-U0', diffBase, '--', file);
643	      const removed = [];
644	      let lineNo = 0;
645	      for (const l of (out || '').split('\n')) {
646	        const hunk = /^@@ -(\d+)(?:,\d+)? \+\d+(?:,\d+)? @@/.exec(l);
647	        if (hunk) { lineNo = Number(hunk[1]); continue; }
648	        if (l.startsWith('-') && !l.startsWith('---')) { removed.push({ line: lineNo, text: l.slice(1) }); lineNo += 1; }
649	        else if (!l.startsWith('+')) lineNo += l ? 1 : 0;
650	      }
651	      return removed;
652	    },
653	
654	    conversation() {
655	      if (conversationCache !== undefined) return conversationCache;
656	      if (!transcriptPath || !existsSync(transcriptPath)) return (conversationCache = null);
657	      try { conversationCache = parseEntries(readFileSync(transcriptPath, 'utf8')); }
658	      catch { conversationCache = null; }
659	      return conversationCache;
660	    },
661	
662	    // Every entry the session wrote — the transcript above plus each subagent
663	    // stream beside it — for the rules that judge what the session DID: the
664	    // skills it loaded, the calls it made. `conversation()` stays the session
665	    // file alone, since that is where the owner's turns are. Empty on a surface
666	    // with no transcript, which `conversation()` is what distinguishes from a
667	    // session that did nothing.
668	    sessionEntries() {
669	      if (sessionEntriesCache === undefined) {
670	        sessionEntriesCache = sessionTranscriptPaths(transcriptPath).flatMap((path) => {
671	          // A stream unreadable mid-write costs its own entries, never the others'.
672	          try { return parseEntries(readFileSync(path, 'utf8')); } catch { return []; }
673	        });
674	      }
675	      return sessionEntriesCache;
676	    },
677	
678	    // The branch's own commits since the merge-base, oldest first, each with its
679	    // changed files and committer date — for rules about the ORDER work landed in
680	    // (ctx.commits keeps only messages). Merges excluded: their file list is
681	    // empty under --name-only and their content arrives via their parents.
682	    commitsWithFiles() {
683	      if (!mergeBase) return [];
684	      const out = gitTry(root, 'log', '--reverse', '--no-merges', '--name-only',
685	        '--format=%x00%H%x1f%cI%x1f%s', `${mergeBase}..HEAD`);
686	      const commits = [];
687	      for (const block of (out || '').split('\0')) {
688	        if (!block.trim()) continue;
689	        const [head, ...rest] = block.trim().split('\n');
690	        const [sha, date, subject] = head.split('\x1f');
691	        commits.push({ sha, date, subject, files: rest.map((f) => f.trim()).filter(Boolean) });
692	      }
693	      return commits;
694	    },
695	
696	    // Merge commits the current change introduces — those on HEAD's first-parent
697	    // chain since the merge-base with the base branch (the squash-only effect
698	    // check, scoped to the work). Empty when no base resolves or the branch is
699	    // even with it; pre-existing merges already on the base are out of range.
700	    //
701	    // The range alone trusts the merge-base to be right, and it isn't always: a
702	    // shallow clone's grafted boundary or a criss-cross history can hand back a
703	    // merge-base that sweeps the base branch's own merges into the range. So each
704	    // candidate is confirmed against the base ref itself — a merge already on the
705	    // base branch was never introduced here, whatever the range says. Offline and
706	    // exact, and it holds when refreshBaseRef couldn't run.
707	    introducedMergeCommits() {
708	      if (!mergeBase) return [];
709	      const out = gitTry(root, 'log', '--merges', '--first-parent', '--format=%h %s', `${mergeBase}..HEAD`);
710	      return lines(out).map((l) => {
711	        const i = l.indexOf(' ');
712	        return { sha: l.slice(0, i), subject: l.slice(i + 1) };
713	      }).filter(({ sha }) => !onBaseBranch(sha));
714	    },
715	
716	    // Fixed-string search across tracked files; git grep exits 1 on no match.
717	    // The vendored shared mount is structurally out of the sweep (canon-owned,
718	    // never the project's own code — vendoring/DESIGN.md item 6), so it is
719	    // excluded here exactly as it is from the scanned file set above: a hit
720	    // inside it must never become a finding.
721	    grepTracked(needle) {
722	      const out = gitTry(root, 'grep', '-n', '-F', needle, '--', '.', `:(exclude)${sharedPrefix}`);
723	      return lines(out).map((l) => {
724	        const m = /^([^:]+):(\d+):(.*)$/.exec(l);
725	        return m ? { file: m[1], line: Number(m[2]), text: m[3] } : null;
726	      }).filter(Boolean);
727	    },
728	  };
729	}
730	
731	export const pathDepth = (p) => (p === '.' || p === '' ? [] : p.split(sep));
