1	import { finding } from '../../../engine/checks/helpers/findings.mjs';
2	import { isActive } from '../../../engine/pack_loader/pack-registry.mjs';
3	// Namespace imports with a capability probe, not named ones: the pack and engine
4	// lanes deliver on their own cadences, and a member holding this pack beside an
5	// engine that predates the helper must load the pack rather than fault it.
6	import * as transcript from '../../../engine/checks/helpers/session-transcript.mjs';
7	import * as scoped from '../../../engine/pack_loader/path-scoped-skills.mjs';
8	
9	// The Stop-time half of path-scoped skills. The PreToolUse guard stops a file
10	// tool before the first edit under a scoped pattern; this catches the edits it
11	// never sees — a `sed`, a heredoc, a script — by asking the same question of the
12	// diff: did the session load the skill each changed path is scoped to.
13	const rule = {
14	  id: 'skill-loaded-before-editing',
15	  severity: 'blocking',
16	  description: 'A file a skill forces itself for (force-load-on-file-edits-paths) changed, or a tool call one forces itself for (force-load-on-tool-calls) ran, in a session that never loaded that skill',
17	  doc: 'engine/pack_loader/path-scoped-skills.mjs',
18	  scope: 'work',
19	  why: 'the pack scoped those files to a skill because editing them without it produces work the skill would have prevented; a load after the fact is the review the skill was meant to spare',
20	
21	  run(work) {
22	    if (typeof scoped.pathScopedSkills !== 'function' || typeof transcript.skillLoads !== 'function') return [];
23	    const entries = work.conversation().entries;
24	    if (!entries || !entries.length) return []; // CI and manual runs carry no transcript
25	    const active = work.packs.filter((p) => isActive(p, work.config));
26	    const declarations = scoped.pathScopedSkills(active);
27	    // Session-wide where the engine offers it — a subagent's load lands only in
28	    // its own transcript — the session file alone on an engine that predates it.
29	    const loaded = typeof work.skillLoads === 'function' ? work.skillLoads() : transcript.skillLoads(entries);
30	    const out = [];
31	    for (const file of declarations.length ? work.changedFiles : []) {
32	      for (const d of scoped.missingSkillsFor(file, declarations, loaded)) {
33	        out.push(finding(rule, {
34	          file,
35	          what: `changed under ${d.files}, which the ${d.pack} pack's \`${d.skill}\` skill forces itself for, and this session never loaded that skill`,
36	          fix: `load it now — Skill tool, skill: "${d.skill}", or Read its SKILL.md — and re-read the change against what it says before stopping`,
37	        }));
38	      }
39	    }
40	    // The tool-call half: a call a skill forces itself for, in a session that
41	    // never loaded it. Judged against the whole session's loads like the path
42	    // half — the PreToolUse guard holds the call until the load, and what is left
43	    // for Stop is the session that loaded it never; a load now, with the re-read
44	    // the fix asks for, is what converges the finding.
45	    if (typeof scoped.triggeredSkills === 'function' && typeof work.toolCalls === 'function') {
46	      const triggers = scoped.triggeredSkills(active).filter((d) => d.kind === 'toolCall');
47	      const reported = new Set();
48	      for (const call of triggers.length ? work.toolCalls() : []) {
49	        for (const d of scoped.missingSkillsForCall(call, triggers, loaded)) {
50	          if (reported.has(d.skill)) continue;
51	          reported.add(d.skill);
52	          out.push(finding(rule, {
53	            file: `(session) ${call.name} call`,
54	            what: `a ${call.name} call the ${d.pack} pack's \`${d.skill}\` skill forces itself for (${d.source}) ran, and this session never loaded that skill`,
55	            fix: `load it now — Skill tool, skill: "${d.skill}", or Read its SKILL.md — and re-read what the call did against what it says before stopping`,
56	          }));
57	        }
58	      }
59	    }
60	    return out;
61	  },
62	};
63	
64	export default rule;
