40	  const x = scale(axis);
41	  const rows = board.groups.reduce((n, g) => n + HEADER_H + g.shown.length * ROW_H + (g.more ? 20 : 0), 0);
42	  const height = PAD_TOP + rows + 12;
43	  const svg = svgEl('svg', {
44	    viewBox: `0 0 ${VIEW_W} ${height}`, class: 'board', role: 'img',
45	    'aria-label': 'Work board — twelve day columns, seven back and four ahead, with one lane per flow',
46	  });
