48	  // --- the axis -------------------------------------------------------------------
49	  const nowX = x(axis.now);
50	  svg.append(svgEl('rect', { x: GUTTER, y: PAD_TOP - 8, width: nowX - GUTTER, height: height - PAD_TOP, fill: 'var(--wash)' }));
51	  for (const day of axis.days) {
52	    const dx = x(day.start);
53	    svg.append(svgEl('line', { x1: dx, y1: PAD_TOP - 8, x2: dx, y2: height - 12, stroke: 'var(--ledger)', 'stroke-width': 1 }));
