55	    label.textContent = day.today ? 'today' : day.day.slice(5);
56	    svg.append(label);
57	    // The anchor tick — where every scheduled thing on this board sits.
58	    const ax = x(day.anchorAt);
59	    svg.append(svgEl('line', { x1: ax, y1: PAD_TOP - 6, x2: ax, y2: PAD_TOP - 2, stroke: 'var(--muted)', 'stroke-width': 1 }));
60	  }
61	  svg.append(svgEl('line', { x1: nowX, y1: PAD_TOP - 8, x2: nowX, y2: height - 12, stroke: 'var(--ink)', 'stroke-width': 1 }));
62	  const flag = svgEl('text', { x: nowX + 4, y: height - 3, class: 'axis-now' });
63	  flag.textContent = `now · ${new Date(axis.now).toISOString().slice(0, 16).replace('T', ' ')} UTC`;
64	  svg.append(flag);
65	
66	  // --- the groups -----------------------------------------------------------------
67	  let y = PAD_TOP + 6;
68	  for (const group of board.groups) {
69	    // The title in the gutter, the group's ONE derived sentence in the lane. Nothing
70	    // else: every other count about a group is a hover.
71	    svg.append(text(6, y + 12, `${group.title.toUpperCase()} · ${group.count}`, 'group'));
72	    svg.append(text(GUTTER + 6, y + 12, group.sentence, 'group-note'));
73	    svg.append(svgEl('line', { x1: 0, y1: y + 18, x2: VIEW_W, y2: y + 18, stroke: 'var(--rule)' }));
74	    y += HEADER_H;
75	
76	    for (const row of group.shown) {
77	      const mid = y + ROW_H / 2;
78	      if (group.grid) drawGridRow(svg, row, axis, x, mid, onSelect);
79	      else drawLaneRow(svg, row, axis, x, mid, onSelect, repo);
80	      y += ROW_H;
81	    }
82	    if (group.more) {
83	      svg.append(text(GUTTER + 6, y + 12, `${group.more} more row${group.more === 1 ? '' : 's'}`, 'more'));
84	      y += 20;
