90	function text(px, py, content, cls) {
91	  const t = svgEl('text', { x: px, y: py, class: cls });
92	  t.textContent = content;
93	  return t;
94	}
95	
96	// The SVG counterpart of `refNodes`: one text element whose `#N` runs are anchors, so
97	// a gutter naming a PR and the issue it closes opens either one. With no repo to link
98	// against — a board drawn outside a member — it is the plain text element above.
99	function refText(px, py, content, cls, repo) {
100	  if (!repo) return text(px, py, content, cls);
101	  const t = svgEl('text', { x: px, y: py, class: cls });
102	  for (const part of splitRefs(content)) {
103	    const span = svgEl('tspan');
104	    span.textContent = part;
105	    if (!isRef(part)) { t.append(span); continue; }
106	    const link = svgEl('a', { href: issueUrl(repo, part.slice(1)), target: '_blank', rel: 'noopener' });
107	    link.append(span);
108	    t.append(link);
109	  }
110	  return t;
111	}
112	
113	// A lane row: its gutter name, its marks, and — spent only on a FINDING — one line of
114	// text in the serious tint. Every age, count and policy sentence is in the hover.
115	function drawLaneRow(svg, row, axis, x, mid, onSelect, repo = null) {
116	  svg.append(refText(6, mid + 4, row.gutter, 'gutter', repo));
117	
118	  for (const mark of row.marks) {
119	    if (mark.kind === 'bar') {
120	      const from = Math.max(mark.from, axis.from);
121	      const bar = titled(svgEl('rect', {
122	        x: x(from), y: mid - 5, width: Math.max(3, x(mark.to) - x(from)), height: 10, rx: 2,
123	        fill: 'var(--machine-wash)', stroke: 'var(--machine)', 'stroke-width': 1, class: 'mark',
124	      }), `${row.gutter} — ${row.title}\nopen since ${new Date(mark.from).toISOString().slice(0, 10)}\n${row.why}`);
125	      bar.addEventListener('click', () => onSelect(row));
126	      svg.append(bar);
127	      if (mark.from < axis.from) svg.append(text(GUTTER - 8, mid + 4, '◂', 'edge'));
128	      // The one warm thing on the board, and a separate mark rather than an end-cap so
129	      // it is findable from across the sheet.
130	      if (mark.flag) {
131	        svg.append(titled(svgEl('polygon', {
132	          points: `${x(mark.to)},${mid - 9} ${x(mark.to) - 5},${mid - 17} ${x(mark.to) + 5},${mid - 17}`,
133	          fill: 'var(--you)', class: 'mark',
134	        }), `waits for a person — ${row.why}`));
135	      }
136	      continue;
137	    }
138	    if (mark.at === null) {
139	      // No time at all: the lane is drawn broken, from the gutter to the break.
140	      const bx = x(axis.now);
141	      svg.append(svgEl('line', {
142	        x1: GUTTER, y1: mid, x2: bx - 14, y2: mid,
143	        stroke: row.broken ? 'var(--critical)' : 'var(--muted)', 'stroke-width': 1, 'stroke-dasharray': '4 3',
144	      }));
145	      svg.append(text(bx - 10, mid + 4, '»', row.broken ? 'break' : 'edge'));
146	      const node = titled(svgEl('circle', {
147	        cx: bx + 6, cy: mid, r: 5, fill: 'none', stroke: 'var(--ink-2)', 'stroke-dasharray': '2 2', class: 'mark',
148	      }), `${row.gutter} — ${row.why}`);
149	      node.addEventListener('click', () => onSelect(row));
150	      svg.append(node);
151	      continue;
152	    }
153	    const cx = x(mark.at);
154	    let node;
155	    if (mark.kind === 'running') {
156	      node = svgEl('circle', { cx, cy: mid, r: 5, fill: 'var(--machine)', class: 'mark' });
157	    } else if (mark.kind === 'park') {
158	      node = parkMark(cx, mid, mark.park);
159	    } else {
160	      node = svgEl('circle', { cx, cy: mid, r: 5, fill: 'none', stroke: 'var(--ink-2)', 'stroke-width': 1.4, class: 'mark' });
161	    }
162	    titled(node, `${row.gutter} — ${row.title}\n${row.why}`);
163	    node.addEventListener('click', () => onSelect(row));
164	    svg.append(node);
165	  }
166	
167	  if (row.finding) svg.append(refText(GUTTER + 6, mid + 16, row.finding, 'finding', repo));
168	}
169	
170	// A park's KIND is its glyph, so the four are told apart without colour.
171	const PARK_GLYPH = { action: '×', approval: '–', decision: '?', failure: '' };
172	function parkMark(cx, cy, kind) {
173	  const g = svgEl('g', { class: 'mark' });
174	  const hue = kind === 'approval' ? 'var(--you)' : kind === 'failure' ? 'var(--critical)' : 'var(--serious)';
175	  g.append(svgEl('rect', {
176	    x: cx - 6, y: cy - 6, width: 12, height: 12,
177	    fill: kind === 'failure' ? 'var(--wash)' : 'none', stroke: hue, 'stroke-width': 1.4,
178	  }));
179	  if (kind === 'failure') {
180	    // Hatched, so the worst park is distinguishable with no colour at all.
181	    for (let i = -6; i <= 6; i += 4) {
182	      g.append(svgEl('line', { x1: cx + i, y1: cy - 6, x2: cx + i + 6, y2: cy + 6, stroke: hue, 'stroke-width': 0.8 }));
183	    }
184	  } else {
185	    const glyph = svgEl('text', { x: cx, y: cy + 4, class: 'glyph', fill: hue, 'text-anchor': 'middle' });
186	    glyph.textContent = PARK_GLYPH[kind] ?? '?';
187	    g.append(glyph);
188	  }
189	  return g;
190	}
191	
192	// A task's row in the schedule grid: one cell per day, at the day's anchor.
193	const CELL_W = 18;
194	const CELL_H = 12;
195	
196	function drawGridRow(svg, row, axis, x, mid, onSelect) {
197	  svg.append(text(6, mid + 4, row.task, 'gutter'));
198	  for (const cell of row.cells) {
199	    const day = axis.days.find((d) => d.day === cell.day);
200	    if (!day || cell.state === 'none') continue;
201	    const cx = x(day.anchorAt);
202	    const node = gridCell(cell, cx, mid);
203	    titled(node, `${row.task} · ${cell.day} · ${cell.state}${cell.count > 1 ? ` ×${cell.count}` : ''}`);
204	    node.addEventListener('click', () => onSelect({ ...row, kind: 'task', cell }));
205	    svg.append(node);
206	    if (cell.count > 1) {
207	      const n = svgEl('text', {
208	        x: cx, y: mid + 3.5, class: 'cell-count', 'text-anchor': 'middle',
209	        fill: cell.state === 'ran' ? 'var(--sheet)' : 'var(--ink-2)',
210	      });
211	      n.textContent = String(cell.count);
212	      svg.append(n);
213	    }
214	  }
215	}
216	
217	function gridCell(cell, cx, cy) {
218	  const g = svgEl('g', { class: 'mark' });
219	  const box = (attrs) => svgEl('rect', { x: cx - CELL_W / 2, y: cy - CELL_H / 2, width: CELL_W, height: CELL_H, ...attrs });
220	  switch (cell.state) {
221	    case 'ran': return g.append(box({ fill: 'var(--good)' })), g;
222	    case 'declined': return g.append(box({ fill: 'none', stroke: 'var(--muted)' })), g;
223	    case 'parked': return g.append(box({ fill: 'var(--you)' })), g;
224	    case 'running': return g.append(svgEl('circle', { cx, cy, r: 5, fill: 'var(--machine)' })), g;
225	    case 'predicted': return g.append(box({ fill: 'none', stroke: 'var(--machine)' })), g;
226	    // Half-height, never a dash: at three pixels a dash pattern is invisible.
227	    case 'will-decline':
228	      g.append(svgEl('rect', { x: cx - CELL_W / 2, y: cy - CELL_H / 4, width: CELL_W, height: CELL_H / 2, fill: 'none', stroke: 'var(--muted)' }));
229	      return g;
230	    case 'failure-park':
231	    default: {
232	      g.append(box({ fill: 'var(--wash)', stroke: 'var(--critical)', 'stroke-width': 1.2 }));
233	      for (let i = -CELL_W / 2; i <= CELL_W / 2; i += 4) {
234	        g.append(svgEl('line', { x1: cx + i, y1: cy - CELL_H / 2, x2: cx + i + CELL_H, y2: cy + CELL_H / 2, stroke: 'var(--critical)', 'stroke-width': 0.7 }));
235	      }
236	      return g;
237	    }
238	  }
239	}
240	
241	// The quiet tail: one ruled line, not a group, with the three counts that matter and a
242	// disclosure naming the issues behind them.
243	export function quietLine(quiet, { repo = null } = {}) {
244	  const line = (i) => ` · ${i.title} — idle ${i.idleDays} d${i.quickWin ? ' · quick-win' : ''}${i.needsDecision ? ' · needs-decision (a decision park by another name)' : ''}`;
245	  const list = el('div', { className: 'detail quiet-list', hidden: true }, [
246	    el('ul', {}, quiet.items.slice(0, 40).map((i) => el('li', {}, [
247	      repo ? issueLink(repo, i.number) : `#${i.number}`,
248	      line(i),
249	    ]))),
250	  ]);
251	  const button = el('button', { className: 'expand', type: 'button', textContent: 'show ▾' });
252	  button.setAttribute('aria-expanded', 'false');
253	  button.addEventListener('click', () => {
254	    list.hidden = !list.hidden;
255	    button.setAttribute('aria-expanded', String(!list.hidden));
256	    button.textContent = list.hidden ? 'show ▾' : 'show ▴';
257	  });
258	  return el('div', { className: 'quiet' }, [
259	    el('div', { className: 'quiet-head' }, [
260	      el('span', { textContent: `${quiet.total} issue${quiet.total === 1 ? '' : 's'}, quiet — plain, on no edge` }),
261	      el('span', { className: 'n', textContent: `${quiet.rotting} rotting · ${quiet.quickWin} quick-win · ${quiet.needsDecision} needs-decision` }),
262	      quiet.total ? button : null,
263	    ]),
264	    list,
265	  ]);
266	}
