// The Work board's marks, drawn. One SVG that scales to its container; every shape here
// is named in the identity's mark table ([docs/visual-identity.md](docs/visual-identity.md)),
// and the decisions behind them were all made in [`board.mjs`](board.mjs).
//
// FORM BEFORE COLOUR on every mark, so the board reads in either theme and in
// greyscale: predicted and declined differ by HEIGHT rather than by a dash pattern
// invisible at three pixels, a park's kind is its glyph, and a plain issue is a diamond
// whatever state it is in.
//
// THE PAST IS WASHED, NOW IS SOLID, THE FUTURE IS HOLLOW — the same grammar the wake
// strip and the pulse obey, so one reader learns it once.

import { el, issueLink, issueUrl, splitRefs, isRef } from './ui.mjs';
import { svgEl } from './sheet.mjs';

const VIEW_W = 1000;
const GUTTER = 168;
const ROW_H = 36;
const HEADER_H = 30;
const PAD_TOP = 16;

const titled = (node, text) => {
  if (!text) return node;
  const label = svgEl('title');
  label.textContent = text;
  node.append(label);
  return node;
};

// Where an instant sits on the axis. Clamped to the lane, so a PR opened before the
// window still draws — with a `◂` note saying its real start is off the edge.
const scale = (axis) => (at) => {
  const span = axis.to - axis.from;
  const x = GUTTER + ((at - axis.from) / span) * (VIEW_W - GUTTER);
  return Math.max(GUTTER, Math.min(VIEW_W, x));
};

export function renderBoard(board, { onSelect = () => {}, repo = null } = {}) {
  const { axis } = board;
  const x = scale(axis);
  const rows = board.groups.reduce((n, g) => n + HEADER_H + g.shown.length * ROW_H + (g.more ? 20 : 0), 0);
  const height = PAD_TOP + rows + 12;
  const svg = svgEl('svg', {
    viewBox: `0 0 ${VIEW_W} ${height}`, class: 'board', role: 'img',
    'aria-label': 'Work board — twelve day columns, seven back and four ahead, with one lane per flow',
  });

  // --- the axis -------------------------------------------------------------------
  const nowX = x(axis.now);
  svg.append(svgEl('rect', { x: GUTTER, y: PAD_TOP - 8, width: nowX - GUTTER, height: height - PAD_TOP, fill: 'var(--wash)' }));
  for (const day of axis.days) {
    const dx = x(day.start);
    svg.append(svgEl('line', { x1: dx, y1: PAD_TOP - 8, x2: dx, y2: height - 12, stroke: 'var(--ledger)', 'stroke-width': 1 }));
    const label = svgEl('text', { x: dx + 3, y: PAD_TOP - 1, class: 'axis-day' });
    label.textContent = day.today ? 'today' : day.day.slice(5);
    svg.append(label);
    // The anchor tick — where every scheduled thing on this board sits.
    const ax = x(day.anchorAt);
    svg.append(svgEl('line', { x1: ax, y1: PAD_TOP - 6, x2: ax, y2: PAD_TOP - 2, stroke: 'var(--muted)', 'stroke-width': 1 }));
  }
  svg.append(svgEl('line', { x1: nowX, y1: PAD_TOP - 8, x2: nowX, y2: height - 12, stroke: 'var(--ink)', 'stroke-width': 1 }));
  const flag = svgEl('text', { x: nowX + 4, y: height - 3, class: 'axis-now' });
  flag.textContent = `now · ${new Date(axis.now).toISOString().slice(0, 16).replace('T', ' ')} UTC`;
  svg.append(flag);

  // --- the groups -----------------------------------------------------------------
  let y = PAD_TOP + 6;
  for (const group of board.groups) {
    // The title in the gutter, the group's ONE derived sentence in the lane. Nothing
    // else: every other count about a group is a hover.
    svg.append(text(6, y + 12, `${group.title.toUpperCase()} · ${group.count}`, 'group'));
    svg.append(text(GUTTER + 6, y + 12, group.sentence, 'group-note'));
    svg.append(svgEl('line', { x1: 0, y1: y + 18, x2: VIEW_W, y2: y + 18, stroke: 'var(--rule)' }));
    y += HEADER_H;

    for (const row of group.shown) {
      const mid = y + ROW_H / 2;
      if (group.grid) drawGridRow(svg, row, axis, x, mid, onSelect);
      else drawLaneRow(svg, row, axis, x, mid, onSelect, repo);
      y += ROW_H;
    }
    if (group.more) {
      svg.append(text(GUTTER + 6, y + 12, `${group.more} more row${group.more === 1 ? '' : 's'}`, 'more'));
      y += 20;
    }
  }
  return svg;
}

function text(px, py, content, cls) {
  const t = svgEl('text', { x: px, y: py, class: cls });
  t.textContent = content;
  return t;
}

// The SVG counterpart of `refNodes`: one text element whose `#N` runs are anchors, so
// a gutter naming a PR and the issue it closes opens either one. With no repo to link
// against — a board drawn outside a member — it is the plain text element above.
function refText(px, py, content, cls, repo) {
  if (!repo) return text(px, py, content, cls);
  const t = svgEl('text', { x: px, y: py, class: cls });
  for (const part of splitRefs(content)) {
    const span = svgEl('tspan');
    span.textContent = part;
    if (!isRef(part)) { t.append(span); continue; }
    const link = svgEl('a', { href: issueUrl(repo, part.slice(1)), target: '_blank', rel: 'noopener' });
    link.append(span);
    t.append(link);
  }
  return t;
}

// A lane row: its gutter name, its marks, and — spent only on a FINDING — one line of
// text in the serious tint. Every age, count and policy sentence is in the hover.
function drawLaneRow(svg, row, axis, x, mid, onSelect, repo = null) {
  svg.append(refText(6, mid + 4, row.gutter, 'gutter', repo));

  for (const mark of row.marks) {
    if (mark.kind === 'bar') {
      const from = Math.max(mark.from, axis.from);
      const bar = titled(svgEl('rect', {
        x: x(from), y: mid - 5, width: Math.max(3, x(mark.to) - x(from)), height: 10, rx: 2,
        fill: 'var(--machine-wash)', stroke: 'var(--machine)', 'stroke-width': 1, class: 'mark',
      }), `${row.gutter} — ${row.title}\nopen since ${new Date(mark.from).toISOString().slice(0, 10)}\n${row.why}`);
      bar.addEventListener('click', () => onSelect(row));
      svg.append(bar);
      if (mark.from < axis.from) svg.append(text(GUTTER - 8, mid + 4, '◂', 'edge'));
      // The one warm thing on the board, and a separate mark rather than an end-cap so
      // it is findable from across the sheet.
      if (mark.flag) {
        svg.append(titled(svgEl('polygon', {
          points: `${x(mark.to)},${mid - 9} ${x(mark.to) - 5},${mid - 17} ${x(mark.to) + 5},${mid - 17}`,
          fill: 'var(--you)', class: 'mark',
        }), `waits for a person — ${row.why}`));
      }
      continue;
    }
    if (mark.at === null) {
      // No time at all: the lane is drawn broken, from the gutter to the break.
      const bx = x(axis.now);
      svg.append(svgEl('line', {
        x1: GUTTER, y1: mid, x2: bx - 14, y2: mid,
        stroke: row.broken ? 'var(--critical)' : 'var(--muted)', 'stroke-width': 1, 'stroke-dasharray': '4 3',
      }));
      svg.append(text(bx - 10, mid + 4, '»', row.broken ? 'break' : 'edge'));
      const node = titled(svgEl('circle', {
        cx: bx + 6, cy: mid, r: 5, fill: 'none', stroke: 'var(--ink-2)', 'stroke-dasharray': '2 2', class: 'mark',
      }), `${row.gutter} — ${row.why}`);
      node.addEventListener('click', () => onSelect(row));
      svg.append(node);
      continue;
    }
    const cx = x(mark.at);
    let node;
    if (mark.kind === 'running') {
      node = svgEl('circle', { cx, cy: mid, r: 5, fill: 'var(--machine)', class: 'mark' });
    } else if (mark.kind === 'park') {
      node = parkMark(cx, mid, mark.park);
    } else {
      node = svgEl('circle', { cx, cy: mid, r: 5, fill: 'none', stroke: 'var(--ink-2)', 'stroke-width': 1.4, class: 'mark' });
    }
    titled(node, `${row.gutter} — ${row.title}\n${row.why}`);
    node.addEventListener('click', () => onSelect(row));
    svg.append(node);
  }

  if (row.finding) svg.append(refText(GUTTER + 6, mid + 16, row.finding, 'finding', repo));
}

// A park's KIND is its glyph, so the four are told apart without colour.
const PARK_GLYPH = { action: '×', approval: '–', decision: '?', failure: '' };
function parkMark(cx, cy, kind) {
  const g = svgEl('g', { class: 'mark' });
  const hue = kind === 'approval' ? 'var(--you)' : kind === 'failure' ? 'var(--critical)' : 'var(--serious)';
  g.append(svgEl('rect', {
    x: cx - 6, y: cy - 6, width: 12, height: 12,
    fill: kind === 'failure' ? 'var(--wash)' : 'none', stroke: hue, 'stroke-width': 1.4,
  }));
  if (kind === 'failure') {
    // Hatched, so the worst park is distinguishable with no colour at all.
    for (let i = -6; i <= 6; i += 4) {
      g.append(svgEl('line', { x1: cx + i, y1: cy - 6, x2: cx + i + 6, y2: cy + 6, stroke: hue, 'stroke-width': 0.8 }));
    }
  } else {
    const glyph = svgEl('text', { x: cx, y: cy + 4, class: 'glyph', fill: hue, 'text-anchor': 'middle' });
    glyph.textContent = PARK_GLYPH[kind] ?? '?';
    g.append(glyph);
  }
  return g;
}

// A task's row in the schedule grid: one cell per day, at the day's anchor.
const CELL_W = 18;
const CELL_H = 12;

function drawGridRow(svg, row, axis, x, mid, onSelect) {
  svg.append(text(6, mid + 4, row.task, 'gutter'));
  for (const cell of row.cells) {
    const day = axis.days.find((d) => d.day === cell.day);
    if (!day || cell.state === 'none') continue;
    const cx = x(day.anchorAt);
    const node = gridCell(cell, cx, mid);
    titled(node, `${row.task} · ${cell.day} · ${cell.state}${cell.count > 1 ? ` ×${cell.count}` : ''}`);
    node.addEventListener('click', () => onSelect({ ...row, kind: 'task', cell }));
    svg.append(node);
    if (cell.count > 1) {
      const n = svgEl('text', {
        x: cx, y: mid + 3.5, class: 'cell-count', 'text-anchor': 'middle',
        fill: cell.state === 'ran' ? 'var(--sheet)' : 'var(--ink-2)',
      });
      n.textContent = String(cell.count);
      svg.append(n);
    }
  }
}

function gridCell(cell, cx, cy) {
  const g = svgEl('g', { class: 'mark' });
  const box = (attrs) => svgEl('rect', { x: cx - CELL_W / 2, y: cy - CELL_H / 2, width: CELL_W, height: CELL_H, ...attrs });
  switch (cell.state) {
    case 'ran': return g.append(box({ fill: 'var(--good)' })), g;
    case 'declined': return g.append(box({ fill: 'none', stroke: 'var(--muted)' })), g;
    case 'parked': return g.append(box({ fill: 'var(--you)' })), g;
    case 'running': return g.append(svgEl('circle', { cx, cy, r: 5, fill: 'var(--machine)' })), g;
    case 'predicted': return g.append(box({ fill: 'none', stroke: 'var(--machine)' })), g;
    // Half-height, never a dash: at three pixels a dash pattern is invisible.
    case 'will-decline':
      g.append(svgEl('rect', { x: cx - CELL_W / 2, y: cy - CELL_H / 4, width: CELL_W, height: CELL_H / 2, fill: 'none', stroke: 'var(--muted)' }));
      return g;
    case 'failure-park':
    default: {
      g.append(box({ fill: 'var(--wash)', stroke: 'var(--critical)', 'stroke-width': 1.2 }));
      for (let i = -CELL_W / 2; i <= CELL_W / 2; i += 4) {
        g.append(svgEl('line', { x1: cx + i, y1: cy - CELL_H / 2, x2: cx + i + CELL_H, y2: cy + CELL_H / 2, stroke: 'var(--critical)', 'stroke-width': 0.7 }));
      }
      return g;
    }
  }
}

// The quiet tail: one ruled line, not a group, with the three counts that matter and a
// disclosure naming the issues behind them.
export function quietLine(quiet, { repo = null } = {}) {
  const line = (i) => ` · ${i.title} — idle ${i.idleDays} d${i.quickWin ? ' · quick-win' : ''}${i.needsDecision ? ' · needs-decision (a decision park by another name)' : ''}`;
  const list = el('div', { className: 'detail quiet-list', hidden: true }, [
    el('ul', {}, quiet.items.slice(0, 40).map((i) => el('li', {}, [
      repo ? issueLink(repo, i.number) : `#${i.number}`,
      line(i),
    ]))),
  ]);
  const button = el('button', { className: 'expand', type: 'button', textContent: 'show ▾' });
  button.setAttribute('aria-expanded', 'false');
  button.addEventListener('click', () => {
    list.hidden = !list.hidden;
    button.setAttribute('aria-expanded', String(!list.hidden));
    button.textContent = list.hidden ? 'show ▾' : 'show ▴';
  });
  return el('div', { className: 'quiet' }, [
    el('div', { className: 'quiet-head' }, [
      el('span', { textContent: `${quiet.total} issue${quiet.total === 1 ? '' : 's'}, quiet — plain, on no edge` }),
      el('span', { className: 'n', textContent: `${quiet.rotting} rotting · ${quiet.quickWin} quick-win · ${quiet.needsDecision} needs-decision` }),
      quiet.total ? button : null,
    ]),
    list,
  ]);
}

// claudinite-dashboard — a browser view of what a repo's (or a fleet's) Claudinite
// scheduler is doing, published as a static site.
//
// WHY A PACK AND NOT ENGINE CODE. The dashboard is not part of running the scheduler:
// nothing converges, scheduler runs or executes because it exists, and a member that never
// looks at it should not carry it. Engine code is what every member runs; this is
// content a member OPTS INTO, and adoptable content in this corpus is a pack. That
// also buys it the things a pack has and engine code does not — its own version and
// migration lane, a declaration that gates it, and an adoption moment at which its
// deployment can be wired.
//
// WHAT IT READS. Only the queue's own vocabulary and the task declarations at HEAD,
// through the tasks pack's published `shared-code/`, so the page cannot drift from the
// mechanism it renders. Those relative paths resolve identically in the canon (`packs/<id>/`
// beside its siblings) and in a member's mount (`.claudinite/shared/packs/<id>/`), which is
// why the pack can be read straight out of the mount with nothing rewritten.
//
// NO PROSE. There is no way to write the dashboard wrongly in a consuming repo — it is
// a page, not a practice — and prose here would cost every session in every declaring
// repo tokens for something no session acts on. Its README carries the explanation
// instead and `prose` stays null.
//
// PACKS CONTRIBUTE TO THIS PAGE, as data and never as code. A pack ships a descriptor
// (`packs/<id>/dashboard.json`, found by path convention — nothing registers it) naming
// what it has to say; its values come either from its own generated file in the
// member's tree or from one of the two platform facts the page already reads for every
// member. `descriptor-usable`, this pack's one check, holds a descriptor to what the
// page's OWN reader accepts, which the JSON Schema beside it structurally cannot,
// because the failure is silent — a rejected descriptor renders as one apologetic line
// in someone else's browser and nothing goes red where the author is looking.
//
// PUBLISHING IS A TASK, AND A FOUR-STEP WORKFLOW. `.github/workflows/` is the one
// directory the nightly update can never push to (the Action's `GITHUB_TOKEN` is
// refused there), so whatever the deploy keeps there is frozen at adoption. It keeps
// the least it can: a Pages deploy with source "GitHub Actions" is marketplace actions
// that only workflow YAML can invoke, so the seeded workflow (`seedOps`, below) holds
// exactly those — checkout of `gh-pages`, configure, upload, deploy — and nothing that
// could ever need to change. The `publish-pages` task owns the rest: when to run, the
// build, the push of the built tree to `gh-pages`, the dispatch, the follow-through.
// What adoption cannot do is enable Pages — the handover step below.

export default {
  version: '60906.1',
  minEngineVersion: '60822.1',
  ruleRoutingGuidance: {
    belongs: 'the browser dashboard over Claudinite scheduler state and the site that publishes it',
    excludes: 'how the scheduler behaves — core; workflow practice — git-github; product sites — static-website',
  },

  // Never fingerprinted. Nothing in a repo's shape implies wanting a dashboard, and a
  // scan that suspected one from the presence of a scheduler would suspect it in every
  // member on the fleet.
  seededByDefault: false,

  // The page renders the queue's state, so it reads the queue's own vocabulary and
  // anchor math out of the tasks pack's published `shared-code/` — the one sanctioned
  // cross-pack import in the corpus. Declaring the dependency is what puts that pack
  // in a mount that carries this one.
  requires: ['claudinite-tasks'],

  // A page, not a practice — see the header.

  // ONE question, and it is the one thing this pack cannot pick for a repo: which
  // dashboard the deployment is. Everything else has a default that is right for nearly
  // every project — a pasted token, no canon reference — and is read
  // as optional throughout, an unset key meaning the default rather than a
  // misconfiguration. The mode is not like that: both answers are ordinary, neither is
  // rarer, and guessing it wrong publishes a plausible-looking site covering the wrong
  // thing. So it is asked, and the build refuses to publish without it.
  //
  // config keys — `mode` is REQUIRED, the rest optional:
  //   mode        — "repo" (this repo's own page) or "fleet" (the overview); no default
  //   canonRepo   — the reference member mounts are compared against (fleet view)
  //   rosterUrl   — a roster artifact; more than one member makes the fleet the landing view
  //   repos       — an inline roster instead of a URL
  //   allowedOrigins — page origins allowed to call the exchange endpoint (defaults to
  //                    the redirectUri's origin, then to this owner's Pages host)
  //   workerName  — what the deployed endpoint is called (defaults per the task)
  //
  // The sign-in pair are REPOSITORY VARIABLES rather than config, since they are what an
  // owner sets while standing in the GitHub App's settings and the second is minted by a
  // deploy rather than authored — `CLAUDINITE_DASHBOARD_CLIENT_ID` and
  // `CLAUDINITE_DASHBOARD_EXCHANGE_URL`, both read by `deployment-config.mjs`. A
  // `clientId`/`exchangeUrl` still on a declaration is read as the fallback, so a
  // deployment configured before they existed keeps its button; the build says so once.
  //   owner       — whose repos the fleet view enumerates (defaults to this repo's owner)
  //   exclude     — repos it keeps out (defaults to none)
  questions: [
    {
      id: 'mode',
      prompt: 'Is this deployment this repo\'s OWN dashboard, or the fleet overview across many repos? A fleet deployment also needs to name where its members come from — an "owner" whose repos are enumerated in the browser as the viewer (the one to prefer), or an explicit "repos" list or roster artifact.',
      distill: 'set config.mode to "repo" or "fleet" — there is no default and the build refuses to publish without it; a "fleet" answer must come with a roster source (owner/repos/rosterUrl), and a "repo" answer with none',
    },
  ],

  // The one step adoption CANNOT take, stated where the install flow can print it and
  // the adopting session can file it. Enabling Pages is a repository setting, and
  // `actions/configure-pages`' own `enablement` input cannot do it with the Action's
  // `GITHUB_TOKEN` — it needs a PAT with `repo`, or an app with `administration:write`.
  // Holding a credential that wide, in every member, to save one click is a far worse
  // trade than naming the click. So it is named.
  //
  // In a README this would be met after the first publish had already parked; here it
  // arrives at the moment someone is present and the pack is new.
  adoptionHandover: [
    {
      step: 'Enable GitHub Pages with source "GitHub Actions" — this repo\'s /settings/pages',
      breaks: 'the publish-pages task pushes the build, and its deploy run then fails — the task parks at needs-human-action naming this',
      done: 'the Pages URL serves the dashboard, and a publish-pages run converged done',
    },
    // ONE entry, not the four mechanical steps, because for many deployments the right
    // answer is "nothing" — a member's own dashboard read with a pasted token is on the
    // same 5,000/hour as a signed-in one. What every adopter does have to meet is the
    // DECISION, since until someone makes it their page reads GitHub anonymously; four
    // unconditional checkboxes that are mostly no-ops teach the reader to skim exactly
    // the list that exists to stop them skimming. The mechanics live in the README,
    // where they are read at the moment the answer is yes — and a `step` becomes one
    // checkbox in somebody's handover issue, so spelling them here would put six
    // actions and a rationale inside one box (basics' `writing-handover-issues`).
    {
      step: 'Decide how this dashboard authenticates its viewers: leave it on the pasted-token box, or turn on '
        + 'Sign in with GitHub — the pack README\'s "Turning sign-in on" is that checklist.',
      breaks: 'nothing fails, but a viewer who has not pasted a token reads GitHub anonymously at 60 requests/hour per IP — '
        + 'which one fleet sweep exceeds, so the page serves cached data or empty rows until the hour rolls',
      done: 'a signed-in viewer sees the rate pill read “…/5000 · user”, or this repo has recorded that the token box is '
        + 'this deployment\'s answer',
    },
  ],

  // Seeded, never converged: `.github/workflows/` cannot be written by the nightly, so
  // this arrives once, at adoption, and the repo owns it from there. Only `uses:` steps,
  // for exactly that reason — the part that cannot be updated holds nothing to update.
  seedOps: [
    {
      template: 'stubs/workflows/claudinite-dashboard-pages.yml',
      dest: '.github/workflows/claudinite-dashboard-pages.yml',
    },
  ],
};

content.content:
1	// The ledger sheet's render primitives — the marks the identity
2	// ([docs/visual-identity.md](docs/visual-identity.md)) names, once each.
3	//
4	// ONE TICK VOCABULARY. The heartbeat, the wake strip, the pulse and the sparklines are
5	// the same square mark at four scales, so they are one function each rather than four
6	// chart types: a count is always a number and never a height, and the past is washed,
7	// now is solid and the future is hollow on every timeline here.
8	//
9	// NOTHING DECIDES ANYTHING. Every verdict — which delta is tinted, which square is
10	// critical, what a gap's sentence says — arrives already made, from
11	// [`fleet-ledger.mjs`](fleet-ledger.mjs) and [`fleet.mjs`](fleet.mjs). This file turns
12	// those into nodes.
13	
14	import { el, refNodes } from './ui.mjs';
15	
16	const NS = 'http://www.w3.org/2000/svg';
17	
18	export const svgEl = (tag, attrs = {}) => {
19	  const n = document.createElementNS(NS, tag);
20	  for (const [k, v] of Object.entries(attrs)) if (v !== null && v !== undefined) n.setAttribute(k, String(v));
21	  return n;
22	};
23	
24	const titled = (node, text) => {
25	  if (!text) return node;
26	  const label = svgEl('title');
27	  label.textContent = text;
28	  node.append(label);
29	  return node;
30	};
31	
32	// A band of the sheet: the stub column naming it, its question in the small italic
33	// step, and its body. Bands are the sheet's only structure — there are no cards.
34	export function band(label, question, body, { className = '', aria = null } = {}) {
35	  return el('section', { className: `band ${className}`.trim(), ...(aria ? { ariaLabel: aria } : {}) }, [
36	    el('div', { className: 'stub' }, [
37	      el('span', { className: 'cap', textContent: label }),
38	      question ? el('span', { className: 'q', textContent: question }) : null,
39	    ]),
40	    el('div', { className: 'body' }, [].concat(body)),
41	  ]);
42	}
43	
44	// The one object that sits ON the sheet, on warm paper, because it is the one thing
45	// addressed to the person. Nothing in it clips: it wraps.
46	export function slip({ headline, where, href, chip: chipText, more }) {
47	  return el('div', { className: 'slip' }, [
48	    el('span', { className: 'hl', textContent: headline }),
49	    where ? el('a', { className: 'where', href: href ?? '#', target: '_blank', rel: 'noopener', textContent: where }) : null,
50	    chipText ? el('span', { className: 'chip', textContent: chipText }) : null,
51	    more ? el('span', { className: 'more', textContent: more }) : null,
52	  ]);
53	}
54	
55	// One of the machine's five cells: a status square, its label in condensed caps, the
56	// figure in mono with its unit in the text column, and one line naming the worst
57	// member — a name is what the reader acts on.
58	export function machineCell({ level, label, value, unit, note, extra = null }) {
59	  return el('div', { className: 'cell' }, [
60	    el('div', { className: 'k' }, [
61	      el('i', { className: `sq ${level ?? 'none'}` }),
62	      el('span', { className: 'cap', textContent: label }),
63	    ]),
64	    el('div', { className: 'v' }, [
65	      el('span', { className: value === null ? 'gap' : '', textContent: value === null ? '—' : String(value) }),
66	      unit ? el('span', { className: 'u', textContent: unit }) : null,
67	    ]),
68	    extra,
69	    note ? el('div', { className: 'n', textContent: note }) : null,
70	  ]);
71	}
72	
73	// The heartbeat: one square per member, in the grid's own order. Colour is the verdict
74	// the caller already reached; the hover carries the member and its age.
75	export function beats(members) {
76	  return el('div', { className: 'beat' }, members.map((m) =>
77	    el('i', { className: m.level === 'good' ? '' : m.level, title: m.title })));
78	}
79	
80	// The 24-hour wake strip. One tick per anchor, bucketed by hour, its height the bucket's
81	// count capped so a busy hour cannot dwarf the rest — the count itself is in the hover,
82	// never read off the height.
83	export function wakeTicks(strip, { width = 240, height = 30 } = {}) {
84	  const svg = svgEl('svg', {
85	    viewBox: `0 0 ${width} ${height}`, preserveAspectRatio: 'none',
86	    role: 'img', 'aria-label': 'Scheduled task wakes over the next 24 hours',
87	  });
88	  const base = height - 11;
89	  svg.append(svgEl('line', { x1: 0, y1: base, x2: width, y2: base, stroke: 'var(--ledger)', 'stroke-width': 1 }));
90	  const slot = width / (strip.hours.length || 1);
91	  const peak = Math.max(1, strip.peak);
92	  for (const [i, hour] of strip.hours.entries()) {
93	    for (const [j, task] of hour.tasks.entries()) {
94	      const h = Math.max(4, Math.round((hour.tasks.length / peak) * (base - 1)));
95	      svg.append(titled(svgEl('rect', {
96	        x: Math.round(i * slot + 1 + j * 4), y: base - h, width: 2.5, height: h,
97	        fill: task.held ? 'var(--critical)' : 'var(--machine)',
98	      }), `${hour.hour.slice(11)}:00 — ${task.repo ? `${task.repo} ` : ''}${task.key}${task.held ? ' (held)' : ''}`));
99	    }
100	  }
101	  const label = (x, text, anchor) => {
102	    const t = svgEl('text', { x, y: height - 1, ...(anchor ? { 'text-anchor': anchor } : {}) });
103	    t.textContent = text;
104	    return t;
105	  };
106	  svg.append(label(0, `now ${strip.from?.slice(11) ?? ''}:00`));
107	  svg.append(label(width, '+24h', 'end'));
108	  return el('div', { className: 'wake' }, [svg]);
109	}
110	
111	// A ledger row: figure · text · delta · spark, on the fixed tracks that make the three
112	// columns line up down the whole sheet. The alignment IS the design.
113	export function figureRow(fig, { format = String, repo = null } = {}) {
114	  const value = fig.value === null
115	    ? el('div', { className: 'v gap', textContent: '—' })
116	    : el('div', { className: 'v', textContent: format(fig.value) });
117	  return el('div', { className: 'fig' }, [
118	    value,
119	    el('div', { className: 't' }, [
120	      el('span', { className: 'u', textContent: fig.unit }),
121	      // A gap is stated in the muted step ON ITS OWN LINE, and it REPLACES the
122	      // sub-line rather than joining it: a figure with no number has nothing for a
123	      // second actionable figure to sit beside, and appending the sentence to the
124	      // unit is what makes the row three lines tall and the ledger's tracks stop
125	      // lining up.
126	      fig.gap
127	        ? el('span', { className: 's gap', textContent: fig.gap })
128	        : (fig.sub ? el('span', { className: 's' }, refNodes(repo, fig.sub)) : null),
129	    ]),
130	    deltaCell(fig, format),
131	    el('div', { className: 'sp' }, fig.spark ? [sparkline(fig.spark)] : []),
132	  ]);
133	}
134	
135	// A signed delta in mono, with the base under it. Set in ink UNLESS the figure's own
136	// bad-when rule fired: a merely-down week and a merely-up lead time are figures, not
137	// verdicts, and nothing green is coloured because nothing green needs a person.
138	export function deltaCell(fig, format = String) {
139	  if (fig.delta === null) return el('div', { className: 'd gap', textContent: '—' });
140	  const sign = fig.delta > 0 ? '+' : fig.delta < 0 ? '−' : '±';
141	  return el('div', { className: `d ${fig.bad ? 'bad' : ''}`.trim() }, [
142	    `${sign}${format(Math.abs(fig.delta))}`,
143	    el('span', { className: 'vs', textContent: `vs ${format(fig.previous)}` }),
144	  ]);
145	}
146	
147	// Fourteen marks at row scale: the previous window dimmed, this window in the
148	// machine's blue, and NO MARK AT ALL for a day nobody folded — a blank, never a floor.
149	export function sparkline(series, { width = 74, height = 28 } = {}) {
150	  const svg = svgEl('svg', { viewBox: `0 0 ${width} ${height}`, 'aria-hidden': 'true' });
151	  const known = series.map((d) => d.value).filter((n) => typeof n === 'number');
152	  const peak = known.length ? Math.max(...known, 1) : 1;
153	  const slot = width / (series.length || 1);
154	  const barW = Math.max(2, slot - 1);
155	  const half = Math.floor(series.length / 2);
156	  for (const [i, day] of series.entries()) {
157	    if (typeof day.value !== 'number') continue;
158	    const h = Math.max(1, Math.round((day.value / peak) * height));
159	    svg.append(titled(svgEl('rect', {
160	      x: Math.round(i * slot), y: height - h, width: barW, height: h,
161	      fill: i < half ? 'var(--dim)' : 'var(--machine)',
162	    }), `${day.day} · ${day.value}`));
163	  }
164	  return svg;
165	}
166	
167	// The block's one chart at readable size: sessions per day across the fleet. Today is a
168	// dashed outline because it is not folded yet, and a day no member folded is a blank.
169	export function pulseChart(pulse, { height = 30 } = {}) {
170	  const width = 1000;
171	  const svg = svgEl('svg', {
172	    viewBox: `0 0 ${width} ${height}`, preserveAspectRatio: 'none', role: 'img',
173	    'aria-label': 'Sessions per day across the fleet, 14 days — last week dimmed, this week in the machine\'s blue',
174	  });
175	  svg.append(svgEl('line', { x1: 0, y1: height, x2: width, y2: height, stroke: 'var(--ledger)' }));
176	  const slot = width / (pulse.days.length || 1);
177	  const barW = Math.max(4, slot * 0.62);
178	  const peak = Math.max(1, pulse.peak ?? 1);
179	  for (const [i, day] of pulse.days.entries()) {
180	    const x = Math.round(i * slot + (slot - barW) / 2);
181	    if (day.sessions === null) continue;
182	    const h = Math.max(1, Math.round((day.sessions / peak) * (height - 1)));
183	    const hover = `${day.day} · ${day.sessions} session(s)${day.members.length ? ` · ${day.members.map((r) => r.split('/')[1] ?? r).join(', ')}` : ''}`;
184	    const bar = day.series === 'today'
185	      ? svgEl('rect', {
186	        x, y: 1, width: barW, height: height - 2,
187	        fill: 'none', stroke: 'var(--muted)', 'stroke-dasharray': '3 3',
188	      })
189	      : svgEl('rect', {
190	        x, y: height - h, width: barW, height: h,
191	        fill: day.series === 'previous' ? 'var(--dim)' : 'var(--machine)',
192	      });
193	    svg.append(titled(bar, hover));
194	  }
195	  return svg;
196	}
197	
198	// A detail under the double rule — a ruled table, never a second card.
199	export function detailTable(headers, rows) {
200	  const cell = (c, i) => {
201	    const spec = typeof c === 'object' && c !== null ? c : { text: String(c) };
202	    const td = el('td', {
203	      className: `${headers[i]?.num && !spec.gap ? 'num' : ''} ${spec.gap ? 'gap' : ''}`.trim(),
204	      textContent: spec.text,
205	    });
206	    if (spec.colSpan) td.colSpan = spec.colSpan;
207	    return td;
208	  };
209	  return el('table', {}, [
210	    el('thead', {}, [el('tr', {}, headers.map((h) =>
211	      el('th', { className: `cap${h.num ? ' num' : ''}`, textContent: h.label })))]),
212	    el('tbody', {}, rows.map((cells) => el('tr', {}, cells.map(cell)))),
213	  ]);
214	}
215	
216	// The expand link the totals row carries, and the ruled table it discloses.
217	export function expander(label, target) {
218	  const button = el('button', { className: 'expand', type: 'button', textContent: `${label} ▾` });
219	  button.setAttribute('aria-expanded', 'false');
220	  button.addEventListener('click', () => {
221	    target.hidden = !target.hidden;
222	    button.setAttribute('aria-expanded', String(!target.hidden));
223	    button.textContent = target.hidden ? `${label} ▾` : `${label} ▴`;
224	  });
225	  return button;
226	}
