1	// Shared rendering vocabulary. Both views draw from this so a state, a duration or a
2	// severity looks and reads the same whether you are looking at one repo or twelve —
3	// a fleet page whose "blocked" chip differs from the repo page's is a page you have
4	// to learn twice.
5	
6	import {
7	  BLOCKED, READY, EXECUTING, AGENT,
8	} from '../claudinite-tasks/shared-code/work-items.mjs';
9	// `PARKED` is the page's own key rather than a label: a park is four labels, and
10	// the page groups them into one column (model.mjs).
11	import { PARKED } from './model.mjs';
12	
13	export const $ = (id) => document.getElementById(id);
14	
15	export const el = (tag, props = {}, kids = []) => {
16	  const n = Object.assign(document.createElement(tag), props);
17	  for (const k of [].concat(kids)) if (k !== null && k !== undefined && k !== '') n.append(k);
18	  return n;
19	};
20	
21	// --- formatting ---------------------------------------------------------------
22	
23	const DUR = [['d', 86400e3], ['h', 3600e3], ['m', 60e3]];
24	
25	export function duration(msVal) {
26	  if (msVal == null || !Number.isFinite(msVal)) return '—';
27	  const v = Math.abs(msVal);
28	  for (const [suffix, unit] of DUR) if (v >= unit) return `${Math.floor(v / unit)}${suffix}`;
29	  return '<1m';
30	}
31	
32	export const ago = (at, now) => {
33	  const t = at == null ? null : (typeof at === 'number' ? at : new Date(at).getTime());
34	  return t ? `${duration(now - t)} ago` : '—';
35	};
36	export const until = (date, now) => (date ? `in ${duration(date.getTime() - now)}` : '—');
37	export const stamp = (iso) => (iso ? new Date(iso).toISOString().replace('T', ' ').slice(0, 16) : '—');
38	
39	// --- state and severity ---------------------------------------------------------
40	
41	export const STATE_UI = {
42	  [BLOCKED]:     { cls: 'blocked',   label: 'blocked' },
43	  [READY]:       { cls: 'ready',     label: 'ready' },
44	  [EXECUTING]:   { cls: 'executing', label: 'executing' },
45	  [AGENT]:       { cls: 'agent',     label: 'agent' },
46	  [PARKED]: { cls: 'human',     label: 'needs human' },
47	  torn:          { cls: 'torn',      label: 'torn labels' },
48	  unlabelled:    { cls: 'torn',      label: 'no state label' },
49	  closed:        { cls: 'idle',      label: 'closed' },
50	};
51	
52	// The order the queue's states are shown in everywhere: the sequence an item moves
53	// through, so a row reads left to right as progress.
54	export const STATE_ORDER = [BLOCKED, READY, EXECUTING, AGENT, PARKED];
55	
56	// Keyed by the canonical outcome words `outcomeOf` decodes to, so a spelling
57	// migration in the labels never reaches this table.
58	export const OUTCOME_COLOR = {
59	  done: 'var(--good)',
60	  delivered: 'var(--s-violet)',
61	  obsolete: 'var(--muted)',
62	  none: 'var(--critical)',
63	};
64	
65	export const STATE_COLOR = {
66	  [BLOCKED]: 'var(--s-blue)',
67	  [READY]: 'var(--s-aqua)',
68	  [EXECUTING]: 'var(--s-yellow)',
69	  [AGENT]: 'var(--s-violet)',
70	  [PARKED]: 'var(--critical)',
71	};
72	
73	// Severity always ships as colour PLUS a glyph and words — the status palette is
74	// reserved and never carries meaning on its own.
75	export const LEVEL_GLYPH = { critical: '●', serious: '▲', warning: '▲', info: '·', ok: '✓' };
76	
77	export function chip(state) {
78	  const ui = STATE_UI[state] ?? { cls: 'idle', label: state ?? 'idle' };
79	  return el('span', { className: `chip ${ui.cls}` }, [el('i', { className: 'dot' }), ui.label]);
80	}
81	
82	// A reason naming an item by number — "blocked on #12, #13" — is drawn on the page of
83	// the repo that number belongs to, so it is given one to link against there. The fleet
84	// page's reasons count members and name none, and pass no repo.
85	export const reasonNodes = (reasons, repo = null) =>
86	  reasons.map((r) => el('span', { className: `warn ${r.level}` },
87	    refNodes(repo, `${LEVEL_GLYPH[r.level] ?? '▲'} ${r.text}`)));
88	
89	export const warnNodes = reasonNodes;
90	
91	// --- marks ----------------------------------------------------------------------
92	
93	// A thin proportional bar. Segments are `[label, count, color]`; zero-count segments
94	// are dropped rather than drawn as slivers.
95	export function segmentBar(segments, { width = 108, title = (l, n) => `${n} ${l}` } = {}) {
96	  const bar = el('div', { className: 'bar', style: `width:${width}px` });
97	  let any = false;
98	  for (const [label, count, color] of segments) {
99	    if (!count) continue;
100	    any = true;
101	    bar.append(el('i', { style: `flex:${count};background:${color}`, title: title(label, count) }));
102	  }
103	  if (!any) bar.append(el('i', { className: 'bar-empty', style: 'flex:1' }));
104	  return bar;
105	}
106	
107	// --- the member row's compact marks ----------------------------------------------
108	
109	// A fleet grid is wide, and two of these fold a whole column each back into a mark
110	// the row reads at the same glance. (A third did the same for the star count, until
111	// stars became `git-github`'s contribution and moved to the member's subrow.)
112	
113	// CI as a dot with its age under it. The dot is never the whole message — it carries
114	// a `title` and an `aria-label` in words, because a colour alone is unreadable to a
115	// reader who cannot see the difference between this green and this red.
116	//
117	// The age is bare: "7h", not "7h ago". In a column of them the word is on every row
118	// and carries no information, and the header says what the number is.
119	export function ciMark(ui, when) {
120	  return el('div', { className: 'ci-mark' }, [
121	    el('i', {
122	      className: `dot ${ui.cls}`,
123	      role: 'img',
124	      title: `CI ${ui.label}`,
125	      'aria-label': `CI ${ui.label}`,
126	    }),
127	    el('div', { className: 'sub', textContent: when }),
128	  ]);
129	}
130	
131	// The pack count, with the mount's verdict worn as a badge on it. Two facts that are
132	// read together — how much Claudinite is declared here, and whether what is declared
133	// is current — and almost always the badge says the same thing, so it earns a corner
134	// rather than a column. The detail is the hover.
135	export function packMark(count, mount) {
136	  const badge = MOUNT_BADGE[mount?.state] ?? MOUNT_BADGE.unknown;
137	  return el('div', { className: 'pack-mark', title: badge.title(mount) }, [
138	    el('div', { className: 'n num', textContent: count == null ? '—' : String(count) }),
139	    el('div', { className: `badge ${badge.cls}`, textContent: badge.glyph, role: 'img', 'aria-label': badge.title(mount) }),
140	  ]);
141	}
142	
143	// `unknown` is not `current`: with no canon configured there is nothing to compare
144	// against, and a scheduler run there would claim a check that never happened.
145	const packList = (mount) => (mount.behindPacks ?? [])
146	  .map((p) => `${p.pack} v${p.version} < canon v${p.canonVersion}`).join('\n');
147	
148	const MOUNT_BADGE = {
149	  current: { glyph: '✓', cls: 'ok', title: (m) => `mount current — engine v${m.engineVersion}` },
150	  behind: { glyph: '⏱', cls: 'info', title: (m) => `mount behind canon:\n${packList(m)}` },
151	  'behind-engine': { glyph: '⏱', cls: 'serious', title: (m) => `mount on engine v${m.engineVersion}, canon is v${m.canonEngineVersion}` },
152	  unversioned: { glyph: '?', cls: 'warning', title: () => 'the mount stamp carries no versions — it predates the versioned update flows' },
153	  none: { glyph: '?', cls: 'warning', title: () => 'declares Claudinite but carries no mount stamp' },
154	  unknown: { glyph: '·', cls: 'idle', title: () => 'mount freshness unknown — no canon configured to compare against' },
155	};
156	
157	// A member's last 90 days of commits, as a filled area over time.
158	//
159	// A curve rather than a grid of day-squares: at this size the question a reader is
160	// asking is "is this repo being worked on, and was it always" — a shape answers that
161	// across the column in one glance, where 90 separate squares have to be counted.
162	//
163	// Drawn WEEKLY. A quarter at daily resolution is a sawtooth — an ordinary repo's
164	// weekend is a trough and its Tuesday a spike — and a sawtooth has no shape to read.
165	// The daily counts still supply the total, the peak and the hover.
166	//
167	// Three empty states, and they are three different facts. A null series is a read
168	// that did not happen (withheld for budget, or GitHub still computing); a null DAY is
169	// outside the year of statistics the API returns; and zeroes are a repo that was
170	// genuinely quiet. The curve breaks over unread days rather than drawing them at the
171	// floor, so a gap in the data never renders as a quiet stretch.
172	export function commitGraph(series, { width = 108, height = 26, note = null } = {}) {
173	  if (!series) return el('div', { className: 'sub', textContent: 'not read' });
174	
175	  const NS = 'http://www.w3.org/2000/svg';
176	  const svgEl = (tag, attrs = {}) => {
177	    const n = document.createElementNS(NS, tag);
178	    for (const [k, v] of Object.entries(attrs)) n.setAttribute(k, String(v));
179	    return n;
180	  };
181	
182	  const { days, buckets, total, peak, unread } = series;
183	  const svg = svgEl('svg', {
184	    viewBox: `0 0 ${width} ${height}`, preserveAspectRatio: 'none',
185	    class: 'commits', role: 'img',
186	    'aria-label': `${total} commits over ${days.length} days, busiest day ${peak}`,
187	  });
188	
189	  const step = buckets.length > 1 ? width / (buckets.length - 1) : width;
190	  // Scaled to the row's own busiest WEEK. A shared scale across members was the
191	  // alternative and it is worse: one member vendoring a tree flattens every other row
192	  // to a floor, which is the reading — "nothing happens in these repos" — the column
193	  // exists to disprove. The hover carries the numbers, so the scale is never guessed.
194	  const top = buckets.reduce((n, b) => Math.max(n, b.count ?? 0), 0);
195	  const y = (count) => height - 1 - (top > 0 ? (count / top) * (height - 2) : 0);
196	
197	  // Contiguous runs of READ weeks. A run of one still draws, so a single week
198	  // surrounded by unread ones is visible rather than dropped.
199	  let run = [];
200	  const flush = () => {
201	    if (!run.length) { return; }
202	    const line = run.map((p, i) => `${i ? 'L' : 'M'}${p.x.toFixed(2)},${p.y.toFixed(2)}`).join(' ');
203	    svg.append(svgEl('path', {
204	      d: `${line} L${run[run.length - 1].x.toFixed(2)},${height} L${run[0].x.toFixed(2)},${height} Z`,
205	      class: 'commit-area',
206	    }));
207	    svg.append(svgEl('path', { d: line, class: 'commit-line' }));
208	    run = [];
209	  };
210	  buckets.forEach((b, i) => {
211	    if (b.count == null) { flush(); return; }
212	    run.push({ x: i * step, y: y(b.count) });
213	  });
214	  flush();
215	
216	  const title = svgEl('title');
217	  title.textContent = [
218	    `${total} commit${total === 1 ? '' : 's'} over ${days.length} days, by week`,
219	    peak ? `busiest day ${peak}, busiest week ${top}` : null,
220	    unread ? `${unread} day(s) outside the year GitHub reports` : null,
221	  ].filter(Boolean).join(' · ');
222	  svg.append(title);
223	
224	  return el('div', { className: 'commit-graph' }, [
225	    svg,
226	    el('div', {
227	      className: 'sub',
228	      textContent: [total === 0 && !unread ? 'none' : String(total), note].filter(Boolean).join(' · '),
229	    }),
230	  ]);
231	}
