250	export const issueLink = (repo, n) =>
251	  el('a', { href: issueUrl(repo, n), target: '_blank', rel: 'noopener', textContent: `#${n}` });
252	
253	// A sentence broken into its prose and its `#N` runs, in order — the one place the
254	// page decides what counts as naming an issue. The board's SVG text splits with it too.
255	export const splitRefs = (text) => String(text ?? '').split(/(#\d+)/).filter((part) => part !== '');
256	export const isRef = (part) => /^#\d+$/.test(part);
