258	// A sentence that names issues or pull requests by number, as nodes — the prose
259	// between the numbers unchanged, each number a link. Callers that would have passed a
260	// string to `textContent` pass this as children instead. With no repo to link against
261	// — the fleet page, where a number belongs to no one member — it is the sentence.
262	export const refNodes = (repo, text) => (repo
263	  ? splitRefs(text).map((part) => (isRef(part) ? issueLink(repo, part.slice(1)) : part))
264	  : [String(text ?? '')]);
