269	// --- the lead block --------------------------------------------------------------
270	
271	// The one thing to do, as a card. Both pages render it from the same function so the
272	// fleet's prod and a repo's prod are the same object said the same way.
273	//
274	// It NAMES the work rather than counting it: a count is something to read, and a
275	// title with a link is something to open. The severity is the card's left edge rather
276	// than its words, so an uncoloured card is legible as "nothing is red" at a glance.
277	//
278	// `candidate` is `next-work.mjs`'s pick, or null. `rest` is how many candidates sit
279	// behind it — one piece of work is a prod, and the queue behind it is context.
280	//
281	// `minutes` is priced by the CALLER, from the attention estimate's own rates: this
282	// module renders a figure and never computes one, so the card cannot publish a number
283	// the tiles below would total differently. `note` is whatever that pricing has to
284	// disclaim about it.
285	export function leadCard(candidate, { rest = 0, onRepo = null, minutes = null, note = null } = {}) {
286	  if (!candidate) {
287	    return el('div', { className: 'chart-card lead-card lvl-ok' }, [
288	      el('div', { className: 'lead-why', textContent: 'Nothing is waiting on you.' }),
289	      el('div', { className: 'sub', textContent: 'Nothing read here is parked, failing or behind — the panels below are the picture, not a list to work through.' }),
290	    ]);
291	  }
292	
293	  const where = [];
294	  if (onRepo) {
295	    where.push(el('a', {
296	      href: `?repo=${encodeURIComponent(candidate.repo)}`,
297	      className: 'name',
298	      textContent: candidate.repo,
299	      onclick: (e) => { e.preventDefault(); onRepo(candidate.repo); },
300	    }));
301	  } else {
302	    where.push(el('span', { className: 'name', textContent: candidate.repo }));
303	  }
304	  if (candidate.number != null) {
305	    where.push(issueLink(candidate.repo, candidate.number));
306	    if (candidate.key) where.push(el('span', { className: 'sub', textContent: candidate.key }));
307	  }
308	
309	  // What it costs a person, beside the reason rather than under it: "one item is
310	  // parked" is a fact, "fifteen minutes" is a decision about the next fifteen minutes.
311	  // Work the estimate does not cover — a broken scheduler is not a queue to get
312	  // through — says so rather than showing a zero.
313	  const cost = minutes != null
314	    ? el('div', { className: 'lead-est', title: note ?? '' }, [
315	      el('span', { className: 'v', textContent: `${minutes} min` }),
316	      el('span', { className: 'k', textContent: note ? 'of your time, at least' : 'of your time' }),
317	    ])
318	    : el('div', { className: 'lead-est none' }, [
319	      el('span', { className: 'v', textContent: '—' }),
320	      el('span', { className: 'k', textContent: 'no time estimate' }),
321	    ]);
322	
323	  const kids = [
324	    el('div', { className: 'lead-top' }, [
325	      el('div', { className: 'lead-why', textContent: candidate.why }),
326	      cost,
327	    ]),
328	    el('div', { className: 'lead-where' }, where),
329	  ];
330	  if (candidate.title) kids.push(el('div', { className: 'sub', textContent: candidate.title }));
331	
332	  // How long it has been wrong, when the item knows — an idle time is the queue's own
333	  // measure and is absent on a repo-level fault, which is a state rather than an event.
334	  const detail = [
335	    candidate.idleMs != null ? `untouched for ${duration(candidate.idleMs)}` : null,
336	    ...candidate.more,
337	  ].filter(Boolean);
338	  if (detail.length) kids.push(el('div', { className: 'sub', textContent: detail.join(' · ') }));
339	
340	  kids.push(el('a', {
341	    className: 'lead-act', href: candidate.url, target: '_blank', rel: 'noopener',
342	    textContent: candidate.number != null ? `Open #${candidate.number}` : 'Open the repo',
343	  }));
344	  if (rest > 0) {
345	    kids.push(el('div', { className: 'sub', textContent: `${rest} more after this one.` }));
346	  }
347	  return el('div', { className: `chart-card lead-card lvl-${candidate.level}` }, kids);
348	}
