350	// --- counting up ----------------------------------------------------------------
351	
352	// A fleet load repaints on EVERY member's read landing, so a headline number is
353	// rebuilt a dozen times in a couple of seconds and each rebuild replaces the digits
354	// outright. The eye reads that as flicker rather than as arrival: you cannot tell
355	// whether 7 became 9 or whether two different numbers were drawn.
356	//
357	// So a number that CHANGED tweens from what the reader was last shown to what it is
358	// now, and only that. A first paint has nothing to count from and simply appears; a
359	// value that did not move is not re-animated; anything non-numeric — `3/12`, `—` —
360	// has nothing to interpolate and is set outright.
361	//
362	// `key` is the identity across paints, because the node is not: `replaceChildren`
363	// discards the element the last tween was writing into. It is the tile's own label,
364	// which is what makes two tiles two counters.
365	const displayed = new Map();
366	const inFlight = new Map();
367	
368	const COUNT_MS = 400;
369	
370	// Motion here is decoration on a page whose job is fault-finding, so a reader who has
371	// asked the platform for less of it gets the number and none of the movement.
372	const stillness = () => typeof matchMedia === 'function'
373	  && matchMedia('(prefers-reduced-motion: reduce)').matches;
374	
375	// Decelerating, so the counter reads as landing on its value rather than as stopping
376	// mid-climb.
377	const ease = (t) => 1 - (1 - t) ** 3;
378	
379	export function countUp(node, key, value) {
380	  const stop = inFlight.get(key);
381	  if (stop) { stop(); inFlight.delete(key); }
382	
383	  const to = Number(value);
384	  const from = displayed.get(key);
385	  const set = (n) => { node.textContent = String(n); };
386	
387	  if (!Number.isFinite(to) || typeof requestAnimationFrame !== 'function' || stillness()) {
388	    set(value);
389	    displayed.set(key, Number.isFinite(to) ? to : null);
390	    return node;
391	  }
392	  if (!Number.isFinite(from) || from === to) {
393	    set(to);
394	    displayed.set(key, to);
395	    return node;
396	  }
397	
398	  const t0 = performance.now();
399	  let frame = 0;
400	  const step = (t) => {
401	    // Clamped at BOTH ends. A rAF callback is handed the timestamp of the frame it
402	    // belongs to, which can predate the `performance.now()` taken while scheduling it
403	    // — and a fractionally negative progress run through an ease that overshoots
404	    // backwards drew a counter passing through −12 on its way up from zero.
405	    const p = Math.min(1, Math.max(0, (t - t0) / COUNT_MS));
406	    const at = Math.round(from + (to - from) * ease(p));
407	    set(at);
408	    displayed.set(key, p < 1 ? at : to);
409	    if (p < 1) frame = requestAnimationFrame(step);
410	    else inFlight.delete(key);
411	  };
412	  // The landing value is recorded up front, so a tween cut short by the next paint
413	  // still leaves the counter's memory on the number that paint asked for.
414	  displayed.set(key, from);
415	  set(from);
416	  frame = requestAnimationFrame(step);
417	  inFlight.set(key, () => cancelAnimationFrame(frame));
418	  return node;
419	}
420	
421	// Forget every counter — the next paint's numbers then appear rather than climb.
422	// What a cleared cache and a switched view have in common: the figures after are not
423	// a continuation of the figures before, and tweening between them would draw a
424	// change that did not happen.
425	export const resetCountUps = () => { for (const stop of inFlight.values()) stop(); inFlight.clear(); displayed.clear(); };
426	
427	// --- tiles ----------------------------------------------------------------------
428	
429	// `[value, label, color?, hint?]`. Colour is applied only when the tile is reporting
430	// something — a zero never gets an alarm colour, so a coloured tile always means
431	// "look at this". `hint` may be nodes rather than a string where the tile itemises
432	// what its number is made of.
433	export function tiles(node, rows) {
434	  node.replaceChildren(...rows.map(([v, k, color, hint]) => el('div', { className: 'tile' }, [
435	    countUp(el('div', { className: 'v num', style: color ? `color:${color}` : '' }), k, v),
436	    el('div', { className: 'k', textContent: k }),
437	    hint == null || hint === '' ? null
438	      : (typeof hint === 'string' ? el('div', { className: 'sub', textContent: hint }) : hint),
439	  ])));
440	}
