442	// --- grouped table heads --------------------------------------------------------
443	
444	// A header BAND above the column names, so a wide row reads as a few questions rather
445	// than as a wall of columns. `groups` is `[title, [col, …]]`; a group whose title is
446	// empty spans its columns unlabelled, which is what the identity column at the left
447	// edge wants — it belongs to no question.
448	export const groupedHead = (table, groups) => {
449	  table.replaceChildren();
450	  table.append(el('thead', {}, [
451	    el('tr', { className: 'band' }, groups.map(([title, cols]) =>
452	      el('th', { colSpan: cols.length, className: title ? 'group' : 'group blank', textContent: title }))),
453	    el('tr', {}, groups.flatMap(([, cols], gi) => cols.map((c, ci) =>
454	      el('th', { className: ci === 0 && gi > 0 ? 'group-start' : '', textContent: c })))),
455	  ]));
456	  return table.appendChild(el('tbody'));
457	};
