459	export const columnCount = (groups) => groups.reduce((n, [, cols]) => n + cols.length, 0);
460	
461	// Which cells start a group, so the body can carry the same vertical rule the band
462	// draws. Returns the flat column indexes a `groupedHead(groups)` would open a group at.
463	export const groupStarts = (groups) => {
464	  const out = [];
465	  let i = 0;
466	  for (const [gi, [, cols]] of groups.entries()) {
467	    if (gi > 0) out.push(i);
468	    i += cols.length;
469	  }
470	  return out;
471	};
