473	// --- the day chart --------------------------------------------------------------
474	
475	// A stacked column per day. SVG rather than divs because the whole point is comparing
476	// heights across a fortnight, and one element per segment with a `<title>` gives the
477	// hover text for free.
478	//
479	// The scale is stated, never implied: an unlabelled column chart invites reading two
480	// panels' bars against each other when their maxima differ.
481	export function stackedColumns(days, series, { height = 84, label = (d) => d.day, detail = null } = {}) {
482	  const NS = 'http://www.w3.org/2000/svg';
483	  const svgEl = (tag, attrs = {}) => {
484	    const n = document.createElementNS(NS, tag);
485	    for (const [k, v] of Object.entries(attrs)) n.setAttribute(k, String(v));
486	    return n;
487	  };
488	  // `append` returns nothing, so the title is built and filled before it goes in.
489	  const titled = (node, text) => {
490	    const t = svgEl('title');
491	    t.textContent = text;
492	    node.append(t);
493	    return node;
494	  };
495	
496	  const totals = days.map((d) => series.reduce((n, s) => n + (s.value(d) || 0), 0));
497	  const peak = Math.max(1, ...totals);
498	  const cols = Math.max(1, days.length);
499	  const width = 100;                       // a viewBox unit grid; the CSS sizes it
500	  // The gap is a FRACTION of a column, never a fixed 3 units: at a fortnight of columns
501	  // three units is a hairline, and at two days of hourly ones the gaps alone exceed the
502	  // chart and every bar is drawn at a negative width. Scaling it keeps the same look at
503	  // fourteen columns and keeps the arithmetic valid at any count.
504	  const gap = Math.min(3, (width / cols) * 0.25);
505	  const colW = (width - gap * (cols - 1)) / cols;
506	
507	  const svg = svgEl('svg', {
508	    viewBox: `0 0 ${width} ${height}`, preserveAspectRatio: 'none',
509	    class: 'chart', role: 'img',
510	    'aria-label': `${days.length} days, peak ${peak} on ${days[totals.indexOf(peak)]?.day ?? '—'}`,
511	  });
512	
513	  // What a column is ABOUT, appended to every segment's hover. A stacked bar answers
514	  // "how much"; the reader's next question is always "of what", and on this page that
515	  // means the task names behind the hour — which the tooltip can carry and the chart
516	  // itself has no room for.
517	  const more = (d) => {
518	    const text = detail?.(d);
519	    return text ? `\n${text}` : '';
520	  };
521	
522	  days.forEach((d, i) => {
523	    const x = i * (colW + gap);
524	    let y = height;
525	    let drawn = false;
526	    for (const s of series) {
527	      const v = s.value(d) || 0;
528	      if (!v) continue;
529	      const h = (v / peak) * (height - 2);
530	      y -= h;
531	      drawn = true;
532	      svg.append(titled(svgEl('rect', { x, y, width: colW, height: h, fill: s.color, class: 'col' }),
533	        `${label(d)} — ${v} ${s.label}${more(d)}`));
534	    }
535	    if (!drawn) {
536	      // An empty column is not one thing. A period that was READ and held nothing is a
537	      // floor line; one nothing has answered for yet is left blank, because drawing it
538	      // at the floor would claim a quiet hour the page cannot vouch for.
539	      const unread = d.source === 'none';
540	      svg.append(titled(svgEl('rect', {
541	        x, y: height - 1, width: colW, height: 1, fill: unread ? 'transparent' : 'var(--rule)',
542	      }), `${label(d)} — ${unread ? 'not read' : 'nothing'}${more(d)}`));
543	    }
544	  });
545	
546	  return el('div', { className: 'chart-wrap' }, [
547	    svg,
548	    el('div', { className: 'chart-axis' }, [
549	      el('span', { className: 'sub', textContent: days[0]?.day ?? '' }),
550	      el('span', { className: 'sub', textContent: `peak ${peak}/day` }),
551	      el('span', { className: 'sub', textContent: days[days.length - 1]?.day ?? '' }),
552	    ]),
553	  ]);
554	}
555	
556	export const chartLegend = (series) =>
557	  el('div', { className: 'legend' }, series.map((s) =>
558	    el('span', {}, [el('i', { className: 'sw', style: `background:${s.color}` }), s.label])));
559	
560	// --- two series, two scales -------------------------------------------------------
561	
562	// A line per series, each scaled to ITS OWN maximum, with both maxima printed. Rule
563	// tokens are five figures and check runs are single ones; on a shared axis the second
564	// line is the x-axis and the panel says nothing. On separate scales it says what each
565	// is doing over the month, which is the only question this panel is for.
566	//
567	// THE SCALES ARE STATED, never implied. Two lines at the same height mean nothing
568	// alike, so each axis label carries its series' colour and its own peak, and the panel
569	// is the one place on this page where a reader must not compare heights across lines.
570	//
571	// A NULL BREAKS THE LINE. A day the fold had no opinion on is not a day with zero of
572	// something — a repo that had not folded yet, a shallow checkout that could not see
573	// that far — and drawing it at the floor would be the page inventing a quiet day.
574	export function dualAxisChart(rows, left, right, { height = 96, label = (r) => r.day } = {}) {
575	  const NS = 'http://www.w3.org/2000/svg';
576	  const svgEl = (tag, attrs = {}) => {
577	    const n = document.createElementNS(NS, tag);
578	    for (const [k, v] of Object.entries(attrs)) n.setAttribute(k, String(v));
579	    return n;
580	  };
581	
582	  const width = 100;                       // a viewBox unit grid; the CSS sizes it
583	  const step = rows.length > 1 ? width / (rows.length - 1) : width;
584	  const svg = svgEl('svg', {
585	    viewBox: `0 0 ${width} ${height}`, preserveAspectRatio: 'none', class: 'chart dual', role: 'img',
586	    'aria-label': `${left.label} and ${right.label} over ${rows.length} days, each on its own scale`,
587	  });
588	
589	  const peaks = [left, right].map((s) => rows.reduce((n, r) => Math.max(n, s.value(r) ?? 0), 0));
590	
591	  [left, right].forEach((s, si) => {
592	    const peak = peaks[si] || 1;
593	    let run = [];
594	    const flush = () => {
595	      if (run.length > 1) {
596	        svg.append(svgEl('path', {
597	          d: run.map((p, i) => `${i ? 'L' : 'M'}${p.x.toFixed(2)},${p.y.toFixed(2)}`).join(' '),
598	          class: 'series-line', stroke: s.color,
599	        }));
600	      } else if (run.length === 1) {
601	        // A single read day surrounded by unread ones still has to be visible: a line
602	        // needs two points, so it is drawn as a dot rather than dropped.
603	        svg.append(svgEl('circle', { cx: run[0].x.toFixed(2), cy: run[0].y.toFixed(2), r: 1.2, fill: s.color }));
604	      }
605	      run = [];
606	    };
607	    rows.forEach((r, i) => {
608	      const v = s.value(r);
609	      if (v === null || v === undefined) { flush(); return; }
610	      run.push({ x: i * step, y: height - 2 - (v / peak) * (height - 6) });
611	    });
612	    flush();
613	  });
614	
615	  const axis = (s, peak, cls) => el('span', { className: `sub axis ${cls}` }, [
616	    el('i', { className: 'sw', style: `background:${s.color}` }),
617	    `${s.label} · peak ${s.format ? s.format(peak) : peak}/day`,
618	  ]);
619	
620	  return el('div', { className: 'chart-wrap' }, [
621	    el('div', { className: 'chart-axis' }, [axis(left, peaks[0], 'left'), axis(right, peaks[1], 'right')]),
622	    svg,
623	    el('div', { className: 'chart-axis' }, [
624	      el('span', { className: 'sub', textContent: rows.length ? label(rows[0]) : '' }),
625	      el('span', { className: 'sub', textContent: rows.length ? label(rows[rows.length - 1]) : '' }),
626	    ]),
627	  ]);
628	}
629	
630	// --- moving between views ----------------------------------------------------------
631	
632	// FLIP, hand-rolled: measure where each row is, repaint, then animate it from where it
633	// WAS to where it is now. The page carries no dependencies and this is about forty
634	// lines, so it stays that way.
635	//
636	// Why animate at all on a fault-finding page: switching between stuck / pending / all
637	// is not a new table, it is the SAME rows filtered — and a repaint that swaps one wall
638	// of text for another makes the reader re-find the row they were looking at. Watching
639	// it move keeps it identified.
640	//
641	// Rows are matched across the repaint by `data-k`, because the node is not the same
642	// node: the repaint replaces the body outright.
643	//
644	// A row that LEAVES simply goes. A `<tr>` cannot be animated out of a table's flow
645	// without collapsing the layout around it, and a half-height ghost row is worse than a
646	// clean removal — the arriving and moving rows already carry the change.
647	//
648	// Motion is decoration on a page whose job is fault-finding, so a reader who asked the
649	// platform for less of it gets the repaint and none of the movement.
650	const MOVE_MS = 260;
651	const ENTER_MS = 200;
652	
653	export function flipRows(body, paint) {
654	  const before = new Map();
655	  if (typeof body.getBoundingClientRect === 'function') {
656	    for (const row of body.children) {
657	      if (row.dataset?.k) before.set(row.dataset.k, row.getBoundingClientRect().top);
658	    }
659	  }
660	
661	  paint();
662	
663	  if (stillness() || typeof Element === 'undefined' || typeof Element.prototype.animate !== 'function') return;
664	  for (const row of body.children) {
665	    const k = row.dataset?.k;
666	    const from = k === undefined ? undefined : before.get(k);
667	    if (from === undefined) {
668	      row.animate([{ opacity: 0, transform: 'translateY(6px)' }, { opacity: 1, transform: 'none' }],
669	        { duration: ENTER_MS, easing: 'ease-out' });
670	      continue;
671	    }
672	    const dy = from - row.getBoundingClientRect().top;
673	    if (Math.abs(dy) < 1) continue;
674	    row.animate([{ transform: `translateY(${dy}px)` }, { transform: 'none' }],
675	      { duration: MOVE_MS, easing: 'cubic-bezier(.2,.7,.3,1)' });
676	  }
677	}
678	
679	// --- windowed figures -----------------------------------------------------------
680	
681	// A number with its change against the window before it. The arrow is never the whole
682	// message — the previous window's figure is spelled out, because a delta with nothing
683	// to compare it against is the vanity total this panel exists to avoid.
684	//
685	// Which DIRECTION is good is the caller's to say: more completed work is progress and
686	// more items needing a person is not, and a green up-arrow on the second would read as
687	// a boast about the fleet needing more hand-holding.
688	export function windowFigure(value, label, change, note, { better = 'up' } = {}) {
689	  const arrow = change?.dir === 'up' ? '▲' : change?.dir === 'down' ? '▼' : '—';
690	  const sense = !change || change.dir === 'flat' ? 'flat' : (change.dir === better ? 'good' : 'bad');
691	  return el('div', { className: 'tile' }, [
692	    countUp(el('div', { className: 'v num' }), label, value),
693	    el('div', { className: 'k', textContent: label }),
694	    change
695	      ? el('div', { className: `sub delta ${sense}`, textContent: `${arrow} ${change.by} vs the week before` })
696	      : null,
697	    note ? el('div', { className: 'sub', textContent: note }) : null,
698	  ]);
699	}
