260	      el('b', { textContent: t.costPerMerged === null ? '—' : `≈$${t.costPerMerged}` }),
261	      'per merged PR',
262	      el('span', { className: 'sub', textContent: t.tokensPerMerged === null ? 'not recorded' : `${fmtTokens(Math.round(t.tokensPerMerged))} tok each` }),
263	    ]),
264	    el('div', {}, [
265	      el('b', { textContent: t.autonomy === null ? '—' : `${Math.round(t.autonomy * 100)}%` }),
266	      'autonomy',
267	      el('span', { className: 'sub', textContent: t.humanToAgent === null ? 'yours : agent minutes not recorded' : `yours : agent 1 : ${t.humanToAgent}` }),
268	    ]),
269	    el('div', {}, [
270	      el('b', { textContent: t.caught === null ? '—' : String(t.caught) }),
271	      'would have shipped broken',
272	      expander('per task', detail),
273	    ]),
274	  ]);
275	
276	  const pulseNote = [
277	    ledger.pulse.peak === null ? 'nothing folded' : `peak ${ledger.pulse.peak}`,
278	    'today not folded yet',
279	  ].join(' · ');
280	
281	  $('repo-sheet').replaceChildren(
282	    band('Start here', 'worst thing needing a person', startBody, { aria: 'Start here' }),
283	    band('The machine', 'is this scheduler running, on cadence', machineBody, { aria: 'The machine' }),
284	    band('This week', `against last · ${ledger.window.from} – ${ledger.window.to}`, [
285	      el('div', { className: 'ledger' }, [
286	        column('Got', 'what this repo produced', ledger.ledger.got, [String, String, String], ledger.tails.got),
287	        column('Cost', 'what it took here', ledger.ledger.cost, [fmtTokens, (n) => `≈$${n}`, fmtTokens], ledger.tails.cost),
288	        column('Speed', 'how fast it moves, where it sticks', ledger.ledger.speed, [fmtHours, String, String], ledger.tails.speed),
289	      ]),
290	      totals,
291	      detail,
292	    ], { aria: 'This week against last' }),
293	    band('Pulse', 'sessions / day, 14 days',
294	      el('div', { className: 'pulse' }, [pulseChart(ledger.pulse), el('span', { className: 'n', textContent: pulseNote })]),
295	      { aria: 'Pulse' }),
296	  );
297	}
298	
299	const parkChipFor = (candidate) => {
300	  const minutes = parkMinutes(candidate.park);
301	  const kind = candidate.park?.triage ? String(candidate.park.triage).split('-').pop() : null;
302	  if (minutes == null) return kind ? `${kind} · no time estimate` : 'no time estimate';
303	  return `${minutes} min${kind ? ` · ${kind}` : ''}`;
304	};
305	
306	// The expand only a repo page can offer: what each task closed, what it cost, and what
307	// it kept parking on. Three rows here are STATES rather than tasks — `(none)` is the
308	// share a person started, `(unresolved)` a hole in the record — and they are kept
309	// visible rather than folded into the tasks around them.
310	function perTaskTable(ledger) {
311	  const rows = ledger.perTask.slice(0, 20).map((t) => ([
312	    t.key,
313	    `${t.closed.done + t.closed.delivered} / ${t.closed.obsolete} / ${t.closed.none}`,
314	    t.sessions ?? '—',
315	    t.tokensIn === null ? '—' : fmtTokens(t.tokensIn),
316	    t.tokensPerClose === null ? '—' : fmtTokens(t.tokensPerClose),
317	    t.execFailed || '—',
318	    t.parks || '—',
319	    t.model ?? '—',
320	  ]));
321	  if (!rows.length) rows.push([{ text: 'no task closed anything or spent anything in this window', gap: true, colSpan: 8 }]);
322	  return detailTable([
323	    { label: 'Task' }, { label: 'done / obsolete / none', num: true }, { label: 'Sessions', num: true },
324	    { label: 'Tokens in', num: true }, { label: 'Tok / close', num: true }, { label: 'Exec failed', num: true },
325	    { label: 'Parked', num: true }, { label: 'Model' },
326	  ], rows);
327	}
328	
329	// --- the Work board ---------------------------------------------------------------------
330	
331	// The board and the three tables are one switcher: `board` is `workRows`'s own
332	// classification drawn in time, so the views cannot disagree about what is stuck.
333	function renderWorkBoard(board, { repo, items, prs, rows, now, comments = new Map() }) {
334	  const node = $('work-board');
335	  const explore = $('work-explore');
336	
337	  const open = (row) => {
338	    const number = Number(String(row.gutter).match(/#(\d+)/)?.[1] ?? NaN);
339	    const item = items.find((i) => i.number === number) ?? null;
340	    const parsed = item ? rows.find((r) => r.current?.number === number) : null;
341	    const siblings = parsed ? items.filter((i) => (i.title ?? '').includes(parsed.key)) : [];
342	    const panel = buildPanel(row, {
343	      item, repo, items, prs, rows,
344	      declaration: parsed?.declaration ?? row.row?.declaration ?? null,
345	      siblings,
346	      comments: comments.get(number) ?? null,
347	      cost: ledgerCostFor(row),
348	      now,
349	    });
350	    explore.replaceChildren(el('div', { className: 'explore one' }, [panelNode(panel, repo)]));
351	  };
352	
353	  node.replaceChildren(renderBoard(board, { onSelect: open, repo }), quietLine(board.quiet, { repo }));
354	  // One panel is open at rest — the board's own worst finding written out, because a
355	  // board whose finding is one click away is a board nobody clicks.
356	  const worst = board.groups.flatMap((g) => (g.grid ? [] : g.shown)).find((r) => r.broken || r.parkKind === 'failure')
357	    ?? board.groups[0]?.shown?.[0] ?? null;
358	  if (worst) open(worst);
359	  else explore.replaceChildren();
360	}
361	
362	const ledgerCostFor = () => null;
363	
364	// The CI cell, from `ciStatus`'s own verdict. Failing is CRITICAL here and nowhere
365	// else on the block: nothing the queue lands on a red main is safe, and that is a
366	// different claim from a task being slow.
367	const CI_LEVEL = { passing: 'good', failing: 'critical', running: 'machine', unknown: 'none' };
368	export function ciCell(ci, now) {
369	  return {
370	    level: CI_LEVEL[ci.state] ?? 'none',
371	    word: ci.state === 'unknown' ? null : ci.state,
372	    when: ci.at ? ago(ci.at, now) : '',
373	    note: ci.name ? `${ci.name}${ci.state === 'failing' ? ' — nothing the queue lands is safe' : ''}` : 'no run on the default branch',
374	  };
375	}
376	
377	function panelNode(panel, repo) {
378	  // A panel is mostly numbers — what closes this, what it unblocks, who moves it — and
379	  // every one of them is the reader's next click. The imperative's own command block
380	  // stays literal: it is text to paste, not to follow a link out of.
381	  return el('div', { className: 'panel-x' }, [
382	    el('h4', {}, [panel.title]),
383	    el('dl', {}, panel.fields.flatMap((f) => [
384	      el('dt', { textContent: f.label }),
385	      el('dd', { className: f.value === null ? 'gap' : '' }, refNodes(repo, f.value ?? f.note)),
386	    ])),
387	    el('div', { className: 'do' }, [
388	      el('b', { textContent: 'do' }),
389	      ...(panel.do.includes('\n')
390	        ? [...refNodes(repo, panel.do.split('\n')[0]), el('pre', { textContent: panel.do.split('\n').slice(1).join('\n') })]
391	        : refNodes(repo, panel.do)),
392	    ]),
393	  ]);
394	}
395	
396	export function renderWork(all, repo, now, view, board = null, context = null) {
397	  const counts = viewCounts(all);
398	  const table = $('work');
399	  const boardView = view === 'board';
400	  $('work-board').hidden = !boardView;
401	  $('work-explore').hidden = !boardView;
402	  $('work-table-wrap').hidden = boardView;
403	  if (boardView) {
404	    if (board) renderWorkBoard(board, context);
405	    paintTabs();
406	    return;
407	  }
408	
409	  const paint = () => {
410	    const body = head(table, COLUMNS[view]);
411	    const rows = rowsFor(all, view);
412	    if (!rows.length) { body.append(emptyRow(COLUMNS[view].length, EMPTY[view])); return body; }
413	    for (const r of rows) {
414	      const tr = el('tr', { className: r.level === 'ok' ? '' : `lvl-${r.level}` }, rowCells(r, view, repo, now));
415	      tr.dataset.k = r.key;
416	      body.append(tr);
417	    }
418	    return body;
419	  };
420	
421	  // The first paint has nothing to move from; later ones do.
422	  const body = table.querySelector('tbody');
423	  if (body) flipRows(body, () => paint());
424	  else paint();
425	
426	  paintTabs();
427	
428	  // The board is a tab beside the three tables rather than above them: the same rows,
429	  // drawn in time. Its count is what the board actually holds — lanes plus grid rows —
430	  // so the switcher says what it is offering instead of making the reader click.
431	  function paintTabs() {
432	    const boardCount = board ? board.groups.reduce((n, g) => n + g.count, 0) : 0;
433	    const tabs = board ? ['board', ...VIEWS] : [...VIEWS];
434	    $('work-views').replaceChildren(...tabs.map((v) => el('button', {
435	      className: `view-tab${v === view ? ' on' : ''}`,
436	      textContent: `${v} · ${v === 'board' ? boardCount : counts[v]}`,
437	      'aria-pressed': String(v === view),
438	      onclick: () => renderWork(all, repo, now, v, board, context),
439	    })));
440	  }
441	}
442	
443	// --- what the queue closed -----------------------------------------------------------
444	
445	const OUTCOME_SERIES = [
446	  { label: 'done', color: OUTCOME_COLOR.done, value: (d) => d.done },
447	  { label: 'delivered', color: OUTCOME_COLOR.delivered, value: (d) => d.delivered },
448	  { label: 'obsolete', color: OUTCOME_COLOR.obsolete, value: (d) => d.obsolete },
449	  { label: 'no outcome', color: OUTCOME_COLOR.none, value: (d) => d.none },
450	];
451	
452	function renderOutcomes(series, usage) {
453	  const node = $('work-chart');
454	  const read = series.filter((d) => d.source !== 'none');
455	  const closed = read.reduce((n, d) => n + d.done + d.delivered + d.obsolete + d.none, 0);
456	  node.replaceChildren(
457	    el('div', { className: 'chart-card' }, [
458	      el('div', {
459	        className: 'k',
460	        textContent: usage
461	          ? `${closed} work item(s) closed in ${read.length} folded day(s)`
462	          : 'this repo folds no usage file — only today is visible',
463	      }),
464	      chartLegend(OUTCOME_SERIES),
465	      stackedColumns(series, OUTCOME_SERIES),
466	      el('div', {
467	        className: 'sub',
468	        textContent: 'Today is counted from the live issue page; the days before it from the repo\'s own '
469	          + 'usage fold. A day neither reached is left blank rather than drawn as a quiet one.',
470	      }),
471	    ]),
472	  );
473	}
474	
475	// --- what ran, hour by hour -------------------------------------------------------
476	
477	const RUN_SERIES = [
478	  { label: 'scheduler runs', color: 'var(--s-blue)', value: (h) => h.scheduler },
479	  { label: 'executor runs', color: 'var(--s-aqua)', value: (h) => h.executor },
480	  { label: 'agent sessions', color: 'var(--s-violet)', value: (h) => h.agentic },
481	];
482	
483	// What an hour was ABOUT, for the hover: which tasks executed in it and how they ended.
484	// The runs listing cannot say — nothing in it names a task — so this is the folded
485	// file's answer or nothing, and an hour the fold has not reached says so instead of
486	// implying the hour was empty.
487	function hourDetail(h) {
488	  if (h.source === 'none') return 'not folded yet';
489	  const lines = h.tasks.map((t) => `${t.key}: ${t.statuses.map((s) => `${s.count} ${s.status}`).join(', ')}`);
490	  if (!lines.length) return h.agentic ? 'no task execution recorded' : null;
491	  return lines.join('\n');
492	}
493	
494	function renderRuns(hours) {
495	  const node = $('runs-chart');
496	  const totals = RUN_SERIES.map((s) => hours.reduce((n, h) => n + (s.value(h) ?? 0), 0));
497	  const failed = hours.reduce((n, h) => n + (h.failed ?? 0), 0);
498	  const unfolded = hours.filter((h) => h.source === 'none').length;
499	
500	  node.replaceChildren(
501	    el('div', { className: 'chart-card' }, [
502	      el('div', {
503	        className: 'k',
504	        textContent: `${totals[0]} scheduler · ${totals[1]} executor · ${totals[2]} agent session(s)`
505	          + `${failed ? ` · ${failed} failed` : ''} in ${RUN_HOURS}h`,
506	      }),
507	      chartLegend(RUN_SERIES),
508	      stackedColumns(hours, RUN_SERIES, { label: (h) => `${h.hour.replace('T', ' ')}:00Z`, detail: hourDetail }),
509	      el('div', {
510	        className: 'sub',
511	        textContent: unfolded
512	          ? `${unfolded} of these hours are not in the repo's usage fold, and the live run listing does not `
513	            + 'reach them — they are blank rather than drawn as quiet.'
514	          : 'The freshest hours come from the live run listing; the rest from the repo\'s own usage fold. '
515	            + 'Hover an hour for the tasks that ran in it.',
516	      }),
517	    ]),
518	  );
519	}
520	
521	// --- what the corpus is doing --------------------------------------------------------
522	
523	// The growth panel: what Claudinite put INTO this repo's sessions, and what came back.
524	// Two series on two scales — rule tokens are five figures a day and check runs are
525	// single ones, so a shared axis would draw the second as the x-axis.
526	function renderGrowth(growth) {
527	  const node = $('growth');
528	  if (!growth.folded) {
529	    node.replaceChildren(el('div', { className: 'chart-card' }, [
530	      el('div', { className: 'k', textContent: 'no usage fold in this repo' }),
531	      el('p', {
532	        className: 'sub',
533	        textContent: 'These figures come from `.claudinite/local/usage.GENERATED.json`, which the '
534	          + 'claudinite-growth pack\'s usage-fold task writes. Declare that pack and the panel fills in from '
535	          + 'its first run; nothing else on this page depends on it.',
536	      }),
537	    ]));
538	    return;
539	  }
540	
541	  const left = { label: 'rule tokens in session prompts', color: 'var(--s-violet)', value: (d) => d.ruleTokens, format: (n) => n.toLocaleString() };
542	  const right = { label: 'checks executed', color: 'var(--good)', value: (d) => d.checkRuns };
543	
544	  // The aspirational series. Each is shown when the file carries it and NAMED as absent
545	  // when it does not — a stated gap is information, an empty chart is not.
546	  const optional = [
547	    ['tokens', growth.totals.tokensIn === null ? null
548	      : `${fmt(growth.totals.tokensIn + growth.totals.tokensOut)} tokens spent on sessions`,
549	    'no session in the window recorded token usage'],
550	    ['commits', growth.totals.linesAdded === null ? null
551	      : `${fmt(growth.totals.linesAdded)} lines added · ${fmt(growth.totals.linesRemoved)} removed over ${fmt(growth.totals.commits)} commits`,
552	    'the fold\'s checkout could not read this far back'],
553	    ['releases', growth.totals.releases === null ? null
554	      : `${growth.totals.releases} release${growth.totals.releases === 1 ? '' : 's'} published`,
555	    'the releases listing was not read'],
556	  ];
557	
558	  node.replaceChildren(
559	    el('div', { className: 'chart-card wide' }, [
560	      el('div', {
561	        className: 'k',
562	        textContent: `${fmt(growth.totals.checkRuns)} check run(s), ${fmt(growth.totals.checkFailures)} of them catching something, over ${GROWTH_DAYS} days`,
563	      }),
564	      dualAxisChart(growth.days, left, right),
565	      el('div', { className: 'sub', textContent: `${growth.from} → ${growth.to}. Each line is on its own scale — the two heights do not compare.` }),
566	    ]),
567	    el('div', { className: 'chart-card' }, [
568	      el('div', { className: 'k', textContent: 'and over the same month' }),
569	      el('div', { className: 'needs' }, optional.map(([, said, missing]) =>
570	        el('div', { className: said ? '' : 'sub', textContent: said ?? `not recorded — ${missing}` }))),
571	    ]),
572	  );
573	}
574	
575	const fmt = (n) => (n === null || n === undefined ? '—' : n.toLocaleString());
576	
577	// --- what the packs report ---------------------------------------------------------
578	
579	// LAST on the page, and the only region whose contents differ from repo to repo:
580	// everything above it is the scheduler, which every member has. A repo whose declared
581	// packs contribute nothing never sees the section at all — the common case, since most
582	// packs carry conventions rather than state.
583	function renderContributions(contributions, now) {
584	  const section = $('pack-metrics');
585	  const node = $('pack-cards');
586	  if (!contributions.length) { section.hidden = true; node.replaceChildren(); return; }
587	  section.hidden = false;
588	  node.replaceChildren(...contributions.map((c) => packCard(c, now)));
589	}
590	
591	// --- entry -----------------------------------------------------------------------
592	
593	export async function loadRepo({ repo, token, config = null, onError }) {
594	  gh.resetCounters();
595	  const now = Date.now();
596	
597	  const meta = await gh.getRepo(repo, token);
598	  const headCommit = await gh.getHead(repo, meta.default_branch, token);
599	  const sha = headCommit.sha;
600	
601	  const configText = await settingsTextAtSha(gh, repo, sha, token);
602	  if (!configText) onError?.(`${repo} has no ${SETTINGS_FILE} — it does not run Claudinite, so there are no declared tasks.`);
603	  let declaration = null;
604	  try { declaration = configText ? JSON.parse(configText) : null; } catch {
605	    onError?.(`${SETTINGS_FILE} is present but is not valid JSON — the roster will be empty.`);
606	  }
607	  const schedule = declaration?.taskScheduler ?? null;
608	  if (declaration && !schedule) onError?.('No taskScheduler block — next-anchor times cannot be computed.');
609	
610	  const [{ paths, truncated }, runs, issuePage, usage] = await Promise.all([
611	    gh.listTreeAtSha(repo, sha, token).catch((e) => { onError?.(`The tree could not be read — ${e.message}`); return { paths: [], truncated: false }; }),
612	    gh.listRuns(repo, token).catch((e) => { onError?.(`Actions unreadable — ${e.message}`); return []; }),
613	    gh.listIssues(repo, token),
614	    // The past-data plane. Keyed by the head sha, so this costs one request the first
615	    // time the branch moves and nothing afterwards.
616	    readUsage(repo, sha, token),
617	  ]);
618	  if (truncated) onError?.('GitHub truncated the tree listing — some tasks may be missing from the roster.');
619	
620	  const declPaths = declaration ? taskDeclarationPaths(paths, declaration) : [];
621	  const tasks = await Promise.all(declPaths.map(async (t) => ({
622	    ...t,
623	    declaration: parseDeclaration(await gh.getTextAtSha(repo, sha, t.path, token), t.path),
624	  })));
625	
626	  const items = issuePage.issues.filter(isWorkItem);
627	  // Whether a Blocked-by issue is still open, from the page already fetched. A
628	  // blocker outside that window answers null — unknown, which is never alarmed on.
629	  const byNumber = new Map(issuePage.issues.map((i) => [i.number, i.state === 'open']));
630	  const isOpen = (n) => byNumber.get(n) ?? null;
631	  const rows = buildRoster({ tasks, items, now, schedule, isOpen });
632	  const periodFor = (k) => {
633	    const f = rows.find((r) => r.key === k)?.frequency;
634	    return f && f !== 'manual' ? periodMs(f) : null;
635	  };
636	  const open = items.filter((i) => i.state === 'open').map((i) => describeItem(i, now, { periodFor, isOpen }));
637	
638	  // The canon reference for the drift tile. Optional in every direction: with none
639	  // configured the tile reads `unknown` rather than inventing `current`.
640	  const canon = await readCanon(config, token);
641	  if (canon) await priceStampedPacks(canon, declaration);
642	
643	  // What this repo's own packs report. Discovery is free — the declaration and the
644	  // tree listing are both already in hand — and every read below is content at a sha,
645	  // so a warm load spends nothing on it.
646	  const contributions = await readContributions({ repo, sha, token, declaration, paths, gh });
647	  const needed = liveSourcesNeeded(contributions);
648	  const live = {
649	    stars: meta.stars,
650	    release: needed.has('latest-release') ? await gh.latestRelease(repo, token).catch(() => undefined) : undefined,
651	  };
652	  for (const c of contributions) c.live = live;
653	
654	  const all = workRows(rows, open);
655	  const counts = viewCounts(all);
656	
657	  // The lead, from the same rows the work table is drawn from — one derivation, so the
658	  // block at the top and the first row of the `stuck` view are one verdict.
659	  const candidates = repoCandidates(repo, all);
660	
661	  // The ledger sheet. The rate table is the deployment's own; unset is supported and
662	  // reads *unpriced*, naming the key. The fleet mean is only available where the page
663	  // holds other members' folds, so on a repo-mode deployment it reads *fleet: not read*.
664	  const hours = hourSeries(usage, { now, hours: RUN_HOURS, runs });
665	  const strip = wakeStrip(rows, now);
666	  const ledger = repoLedger({ repo, declaration, usage, items: issuePage.issues, prs: issuePage.prs }, {
667	    now, rates: config?.rates ?? null, fleetMean: config?.fleetTokensPerSession ?? null,
668	  });
669	  const machine = repoMachine({
670	    hourRows: hours,
671	    runSummary: summariseRuns(runs, now, usage),
672	    ci: ciCell(ciStatus(runs, meta.default_branch), now),
673	    usage,
674	    mount: declaration ? mountState(declaration, canon) : null,
675	    canon,
676	    strip,
677	    declaredTasks: tasks.length,
678	    now,
679	  });
680	  renderRepoSheet({ ledger, machine, candidates, strip, repo });
681	
682	  // The board is `workRows`'s own classification drawn in time, from the same issues
683	  // and PRs the tables read — one derivation, so a mark and a row cannot disagree.
684	  const board = buildBoard({ rows, items: issuePage.issues, prs: issuePage.prs, now, schedule });
685	  const boardContext = { repo, items: issuePage.issues, prs: issuePage.prs, rows: all, now };
686	  const anythingLive = counts.stuck || counts.pending;
687	  renderWork(all, repo, now, anythingLive ? 'board' : defaultView(counts), board, boardContext);
688	  renderContributions(contributions, now);
689	  // Today's closes come from the issue page already fetched — the fold's own read is
690	  // watermarked and hourly, so the last hour or two is exactly what it has not seen.
691	  renderOutcomes(queueSeries(usage, {
692	    now,
693	    days: OUTCOME_DAYS,
694	    liveFrom: startOfToday(now),
695	    items: items.filter((i) => i.state === 'closed').map((i) => ({ closedAt: i.closed_at, outcome: outcomeWord(i) })),
696	  }), usage);
697	  renderRuns(hourSeries(usage, { now, hours: RUN_HOURS, runs }));
698	  renderGrowth(growthSeries(usage, { now, days: GROWTH_DAYS }));
699	
700	  return {
701	    now, sha, branch: meta.default_branch, taskCount: tasks.length, itemCount: items.length, issuePage,
702	    usage, generated: usage?.generated ?? null, headCommittedAt: headCommit.committedAt,
703	  };
704	}
705	
706	const startOfToday = (now) => Math.floor(now / 86400e3) * 86400e3;
707	
708	// The item's outcome word, in the same vocabulary the fold writes into the file, so the
709	// live top-up and the folded days stack in one chart.
710	const outcomeWord = (i) => describeItem(i, Date.now()).outcome ?? 'none';
711

