import { test, before } from 'node:test';
import assert from 'node:assert/strict';

// The same few lines of DOM the other view tests use — enough for what a renderer
// touches, and no browser engine to assert that a div got a class.
class FakeEl {
  constructor(tag) { this.tagName = tag; this.children = []; this.textContent = ''; this.className = ''; }
  append(...kids) { for (const k of kids) this.children.push(k); }
  replaceChildren(...kids) { this.children = kids; }
  get classList() { return { add: (c) => { this.className = `${this.className} ${c}`.trim(); } }; }
  get text() {
    return [this.textContent, ...this.children.map((c) => (typeof c === 'string' ? c : c.text))].join('');
  }
  find(cls) {
    const hit = [];
    if (this.className.split(' ').includes(cls)) hit.push(this);
    for (const c of this.children) if (c instanceof FakeEl) hit.push(...c.find(cls));
    return hit;
  }
}

let leadCard;
let refNodes;
let reasonNodes;

before(async () => {
  globalThis.document = { createElement: (tag) => new FakeEl(tag) };
  ({ leadCard, refNodes, reasonNodes } = await import('../ui.mjs'));
});

const candidate = (over = {}) => ({
  kind: 'item',
  repo: 'an-owner/TicketWatch',
  level: 'critical',
  why: 'parked broken — holding the task\'s lane',
  more: [],
  number: 42,
  title: '[claudinite-work] basics/baselining',
  key: 'basics/baselining',
  idleMs: 3 * 86400e3,
  park: { blocking: true, triage: null },
  url: 'https://github.com/an-owner/TicketWatch/issues/42',
  ...over,
});

test('the card names the work, its repo and the issue to open', () => {
  const card = leadCard(candidate());
  assert.match(card.className, /lvl-critical/);
  assert.match(card.text, /holding the task's lane/);
  assert.match(card.text, /an-owner\/TicketWatch/);
  assert.match(card.text, /#42/);
  assert.equal(card.find('lead-act')[0].href, 'https://github.com/an-owner/TicketWatch/issues/42');
});

test('how long it has been wrong is said, when the item knows', () => {
  assert.match(leadCard(candidate()).text, /untouched for 3d/);
  assert.doesNotMatch(leadCard(candidate({ idleMs: null })).text, /untouched/);
});

test('a repo-level fault opens the repo, since there is no issue to open', () => {
  const card = leadCard(candidate({
    kind: 'repo', number: null, title: null, key: null, idleMs: null,
    why: 'scheduler last run failed', url: 'https://github.com/an-owner/TicketWatch',
  }));
  assert.equal(card.find('lead-act')[0].textContent, 'Open the repo');
  assert.doesNotMatch(card.text, /#/);
});

test('what it costs a person is on the card, in its own slot', () => {
  const card = leadCard(candidate(), { minutes: 15 });
  assert.equal(card.find('lead-est')[0].text, '15 minof your time');
});

test('a figure the caller had to disclaim says so on the card', () => {
  const card = leadCard(candidate(), { minutes: 1, note: 'PR size unread, so a lower bound' });
  assert.match(card.find('lead-est')[0].text, /at least/);
});

test('work nothing measures shows no figure rather than a zero', () => {
  const est = leadCard(candidate()).find('lead-est')[0];
  assert.match(est.className, /none/);
  assert.match(est.text, /no time estimate/);
  assert.doesNotMatch(est.text, /\b0\b/);
});

test('what is behind the one is a count, never a second block of work', () => {
  assert.match(leadCard(candidate(), { rest: 4 }).text, /4 more after this one/);
  assert.doesNotMatch(leadCard(candidate(), { rest: 0 }).text, /more after/);
});

test('nothing to prod about is its own card, and it is not coloured as a fault', () => {
  const card = leadCard(null);
  assert.match(card.className, /lvl-ok/);
  assert.match(card.text, /Nothing is waiting on you/);
});

// --- the linkifier -----------------------------------------------------------------

test('every #N in a sentence comes back as an anchor, and the prose between them survives', () => {
  const nodes = refNodes('an-owner/TicketWatch', 'blocked by #12, #13');
  assert.deepEqual(nodes.filter((n) => typeof n === 'string'), ['blocked by ', ', ']);
  const links = nodes.filter((n) => typeof n !== 'string');
  assert.deepEqual(links.map((a) => a.textContent), ['#12', '#13']);
  assert.deepEqual(links.map((a) => a.href), [
    'https://github.com/an-owner/TicketWatch/issues/12',
    'https://github.com/an-owner/TicketWatch/issues/13',
  ]);
});

test('a pull request number takes the same URL as an issue — GitHub redirects it', () => {
  const [link] = refNodes('an-owner/TicketWatch', '#42 lands when you merge PR #43');
  assert.equal(link.href, 'https://github.com/an-owner/TicketWatch/issues/42');
  const pr = refNodes('an-owner/TicketWatch', 'PR #43').at(-1);
  assert.equal(pr.href, 'https://github.com/an-owner/TicketWatch/issues/43');
});

test('text naming no number comes back as itself, so a caller can hand anything to it', () => {
  assert.deepEqual(refNodes('an-owner/TicketWatch', 'not read'), ['not read']);
});

test('a warning that names the items holding a task links each of them', () => {
  const [span] = reasonNodes([{ level: 'warning', text: 'blocked on #12, #13 for over 2 days' }], 'an-owner/TicketWatch');
  assert.equal(span.className, 'warn warning');
  assert.match(span.text, /▲ blocked on #12, #13 for over 2 days/);
  const links = span.children.filter((c) => typeof c !== 'string');
  assert.deepEqual(links.map((a) => a.href), [
    'https://github.com/an-owner/TicketWatch/issues/12',
    'https://github.com/an-owner/TicketWatch/issues/13',
  ]);
});

test('the fleet page passes no repo, and a number stays text rather than a link to nowhere', () => {
  const [span] = reasonNodes([{ level: 'critical', text: '2 items parked broken, #12 the worst' }]);
  assert.match(span.text, /2 items parked broken, #12 the worst/);
  assert.equal(span.children.filter((c) => typeof c !== 'string').length, 0);
});

// The baseline pack: cross-project working discipline, the task lifecycle, and
// the general engineering skills. Declared explicitly like every other pack — no pack is active by
// default. Bootstrap's --init seeds the declaration and the nightly update
// backfills it into existing consumers; never fingerprinted (the declaration is
// authoritative — dropping it is a deliberate choice).
//
// Its skills/ holds general engineering practice every project's work can call for,
// whatever its technology, mounted wherever basics is declared (which --init seeds
// everywhere). When one stops being a baseline activity, its directory moves to the
// pack whose projects need it (#385 moved the git/GitHub and Claudinite-lifecycle
// skills out).
import { contributedBarrierRules } from './barriers.mjs';

export default {
  // A migration record's declared `version` must be ≤ this number, and this number must
  // MOVE for that record to reach a member already at the previous one:
  // `migrationApplies` is `want > have` against the stamped version, and what gets
  // stamped is this manifest's number — so a record declaring a version above it would
  // re-apply every cycle, forever, draining never.
  version: '60906.3',
  minEngineVersion: '60822.1',
  ruleRoutingGuidance: {
    belongs: 'cross-project working discipline, issue-branch-PR lifecycle, repo hygiene, doc/reference integrity and the baseline engineering, testing and debugging skills',
    excludes: 'technology-specific content — its own tech pack; git procedure and GitHub Actions workflow or platform behaviour — git-github',
  },
  seededByDefault: true,
  // `core` is required rather than assumed: this pack is declared everywhere, so
  // the closure is what puts Claudinite's own rules in front of every session.
  // git-github carries the git/GitHub side of the task lifecycle (#385).
  requires: ['claudinite-lifecycle', 'git-github'],
  // The directed folder-access graph, absorbed from the `barriers` pack (#1681):
  // the config-driven `barrier` rule in worldRules/, and this seam, which reads the
  // FIXED barriers other active packs carry as manifest data
  // (contributes: { barriers: [...] }) and builds each into a first-class rule.
  // Composition is declaration + configuration, never a code import
  // (pack-independence) — which is the property the mechanism exists to provide.
  // The guide is barriers.md; the contribution key keeps its own name because it
  // names the mechanism rather than the pack that used to house it.
  contributedRules: (activePacks) => contributedBarrierRules(activePacks),
  // Rules that audit the repo as it stands, whatever this session did.
  // warning-suppression and rules-line-length are declared checks in this
  // pack's declared-checks.json, discovered structurally beside these.
  // Rules that judge the change and the session in front of you — the branch's
  // commits, the diff, the conversation. task-lifecycle and squash-merge-history
  // are declared checks carrying scope: "work", discovered structurally beside
  // these.
  // `task-janitor` and `ci-performance` are this pack's scheduled tasks,
  // discovered by the scheduler's filesystem scan (packs/claudinite-tasks/discover.mjs)
  // rather than declared here.
};

// claudinite-tasks — the whole scheduled-work surface: the queue, the executor, the
// task contract, and the delivery lane a task's output lands through. What the
// mechanism does, and why it is shaped this way, is the canon's own tasks-dispatch design
// document; how it is wired into a repo is this pack's README.
//
// WHY A PACK AND NOT ENGINE CODE. The engine is what every pack's content needs in
// order to EXIST in a repo — discovery, loading, checks, hooks, the mount. Scheduled
// work is not that: a repo that declares no tasks pack runs no scheduled work, and
// that is a supported state rather than a degraded one. Engine membership is decided
// by extending.md's test — would every pack's content stop working without it? — and
// the queue stopped passing it.
//
// WHAT RIDES ALONG. Queue meta-machinery lives here rather than where it historically
// landed, because its subject is this mechanism and nothing else: `task-janitor`
// (the queue's own sweeps, from basics), `usage-fold` (it folds this mechanism's run
// records and outcome labels, from claudinite-growth), and the two task-declaration
// checks (from claudinite-growth). The simulator and its scenario suite — the
// mechanism's executable spec — are in this pack's own test/.
//
// SHARED-CODE IS THE PUBLISHED SURFACE. `shared-code/` is the one place in the corpus
// another pack's code may import across a pack boundary (the `pack-independence`
// barrier's allow list names it, and nothing else). Everything of this pack outside
// it stays off-limits.
//
// SEEDED AT `--init`, NEVER FINGERPRINTED. A new repo gets scheduled work by default —
// the update task is what keeps its Claudinite current, so a member without a queue is
// one nobody is maintaining — and removing the declaration is a durable opt-out, like
// tidy-repo's. Nothing in a repo's SHAPE implies wanting a queue, so there is no
// fingerprint: a scan that suspected one would suspect it everywhere.
//
// Adoption is still a moment a person is present, because it wires two workflow files
// and the routine endpoints a member cannot converge into place.
export default {
  version: '60906.4',
  minEngineVersion: '60822.1',
  ruleRoutingGuidance: {
    belongs: 'scheduled work — the work-item queue, the executor, the task contract and its signals, run records, code-work, delivery',
    excludes: 'authoring a task — claudinite-growth; this repo\'s Claudinite status — claudinite-lifecycle; rendering queue state — claudinite-dashboard',
  },
  seededByDefault: true,
};

