1	#!/usr/bin/env node
2	// The executable form of bootstrap.md: one idempotent invocation, run FROM the
3	// fetched canon tree AGAINST a consumer checkout, that performs every mechanical
4	// part of adoption — seed the declaration, declare the requested packs and record
5	// their interview answers, vendor the snapshot, track it, converge the wiring
6	// (hooks, workflows, rules index, seed local pack), anchor the
7	// scheduler, seed a minimal sweeps CI where none exists — then self-test, sweep,
8	// and report what is left for the session: the pending interview questions
9	// (batched, for ONE AskUserQuestion pass) and the steps only a human can take.
10	//
11	//   node <canon>/bootstrap.mjs --target <consumer-root> --repo <owner>/<repo>
12	//        [--packs id,id,…] [--answer <pack>/<question>=<text>]… [--ref <sha>]
13	//
14	// Adoption is version zero, which is the one state where whole-set vendoring is
15	// safe (see the adopt-claudinite skill on why a stamped repo must never re-run
16	// this). Re-running DURING adoption is the designed loop: record the interview
17	// answers and invoke again — everything converged stays converged.
18	import { existsSync, readFileSync, writeFileSync, appendFileSync, readdirSync, mkdirSync } from 'node:fs';
19	import { execFileSync } from 'node:child_process';
20	import { join, dirname } from 'node:path';
21	import { fileURLToPath, pathToFileURL } from 'node:url';
22	import { discoverPacks, resolveDeclaredPacks, packEntryId } from './engine/pack_loader/pack-registry.mjs';
23	import { seedDeclaration } from './engine/checks/helpers/seed-declaration.mjs';
24	import { loadConfig } from './engine/checks/helpers/repo-context.mjs';
25	import { applyVendor } from './vendoring/apply-vendor-set.mjs';
26	import { convergeWiring } from './engine/converge-wiring.mjs';
27	import { unansweredQuestions } from './packs/claudinite-lifecycle/updates/install.mjs';
28	import { runSelfTest } from './packs/claudinite-lifecycle/updates/engine-update.mjs';
29	
30	const canonRoot = dirname(fileURLToPath(import.meta.url));
31	const args = process.argv.slice(2);
32	const value = (flag) => (args.includes(flag) ? args[args.indexOf(flag) + 1] : null);
33	const values = (flag) => args.flatMap((a, i) => (a === flag ? [args[i + 1]] : []));
34	const fail = (msg) => { console.error(`bootstrap: ${msg}`); process.exit(1); };
35	
36	const target = value('--target') ?? process.cwd();
37	const fullName = value('--repo');
38	if (!fullName || !/^[^/]+\/[^/]+$/.test(fullName)) fail('need --repo <owner>/<repo> — the wiring (cron minute, local pack, executor) is a function of the full name');
39	const requested = values('--packs').flatMap((v) => v.split(',')).map((s) => s.trim()).filter(Boolean);
40	const answers = values('--answer').map((raw) => {
41	  const m = /^([^/=]+)\/([^=]+)=([\s\S]*)$/.exec(raw);
42	  if (!m) fail(`--answer wants <pack>/<question>=<text>, got: ${raw}`);
43	  return { pack: m[1], question: m[2], text: m[3] };
44	});
45	
46	const { packs, errors: packErrors } = await discoverPacks({ localRoot: target });
47	if (packErrors.length) fail(packErrors.map((e) => e.what).join('; '));
48	const byId = new Map(packs.map((p) => [p.id, p]));
49	for (const id of requested) if (!byId.has(id)) fail(`--packs names no canon pack: "${id}" (see packs/directory.GENERATED.md)`);
50	for (const a of answers) {
51	  const q = byId.get(a.pack)?.questions?.find((q) => q.id === a.question);
52	  if (!q) fail(`--answer names no adoption question: ${a.pack}/${a.question}`);
53	}
54	
55	// 1. The declaration: seed if absent, then fold in the requested packs and the
56	// recorded answers. Structural rewrite is safe here and only here — during
57	// adoption the file is this script's own JSON.stringify output, not a
58	// hand-formatted settings file (the anchored-text rule protects the latter).
59	const seedResult = seedDeclaration(target, packs);
60	console.log(seedResult.existed ? 'bootstrap: declaration exists — converging it' : 'bootstrap: seeded .claudinite-settings.json');
61	const declPath = seedResult.path;
62	const decl = JSON.parse(readFileSync(declPath, 'utf8'));
63	const declared = Array.isArray(decl.packs) ? decl.packs : [];
64	for (const id of requested) {
65	  if (!declared.some((e) => packEntryId(e) === id)) { declared.push(id); console.log(`bootstrap: declared ${id}`); }
66	}
67	decl.packs = resolveDeclaredPacks(declared, packs);
68	for (const a of answers) {
69	  const i = decl.packs.findIndex((e) => packEntryId(e) === a.pack);
70	  if (i === -1) fail(`--answer for "${a.pack}", which is not declared — add it via --packs`);
71	  const entry = typeof decl.packs[i] === 'object' ? decl.packs[i] : { id: decl.packs[i] };
72	  entry.answers = { ...(entry.answers ?? {}), [a.question]: a.text };
73	  decl.packs[i] = entry;
74	  console.log(`bootstrap: recorded answer ${a.pack}/${a.question}`);
75	  const distill = byId.get(a.pack).questions.find((q) => q.id === a.question).distill;
76	  if (distill) console.log(`  distill: ${distill}`);
77	}
78	// The scheduler anchors (bootstrap.md's defaults), materialized so the file the
79	// owner would edit shows them.
80	if (!decl.taskScheduler) decl.taskScheduler = { dailyHour: 4, weeklyDay: 'Sun', monthlyDay: 1 };
81	writeFileSync(declPath, `${JSON.stringify(decl, null, 2)}\n`);
82	
83	// 2. Vendor the snapshot (whole-set + stamp; aborts before any write on error).
84	const vendored = await applyVendor(target, { ref: value('--ref') ?? null });
85	if (vendored.errors.length) fail(vendored.errors.map((e) => `${e.what}\n  fix: ${e.fix}`).join('\n'));
86	console.log(`bootstrap: vendored ${vendored.files} files (engine ${vendored.stamp.engineVersion}${vendored.stamp.ref ? `, ref ${vendored.stamp.ref.slice(0, 12)}` : ''})`);
87	
88	// 3. Track it: the two hook-log ignore lines are the WHOLE ignore contract (#385).
89	const ignorePath = join(target, '.gitignore');
90	const ignoreText = existsSync(ignorePath) ? readFileSync(ignorePath, 'utf8') : '';
91	const missing = ['/.claudinite-hooks.log', '/.claudinite-hooks.log.tmp'].filter((l) => !ignoreText.split('\n').includes(l));
92	if (missing.length) {
93	  appendFileSync(ignorePath, (ignoreText && !ignoreText.endsWith('\n') ? '\n' : '') + missing.map((l) => `${l}\n`).join(''));
94	  console.log(`bootstrap: .gitignore ${missing.join(', ')}`);
95	}
96	
97	// 4. Converge the DISTRIBUTION wiring — hooks, the rules index and its CLAUDE.md
98	// import, the mount's git attributes and the repo's own local pack (the one-time seed
99	// only bootstrap passes). Every member carries this set.
100	const config = loadConfig(target);
101	const wiring = await convergeWiring(target, fullName, { seedLocalPack: true });
102	if (wiring.error) fail(wiring.error);
103	console.log(wiring.changed.length ? `bootstrap: wiring — ${wiring.changed.join(', ')}` : 'bootstrap: wiring: already converged');
104	
105	// 4b. …and the SCHEDULING wiring, only for a repo that DECLARED the tasks pack: the two
106	// workflow files belong to the mechanism that runs them, and a repo running no scheduled
107	// work carries neither (#1317). The gate is the declaration rather than the module's
108	// presence in the mount — during the migration the mount carries it either way, so a
109	// presence test would scaffold a queue onto every repo that never asked for one. The
110	// module is then reached through the mount rather than imported, so bootstrap names no
111	// pack it might not have vendored.
112	const declaresTasks = (loadConfig(target)?.packs ?? [])
113	  .some((e) => (typeof e === 'string' ? e : e?.id) === 'claudinite-tasks');
114	const scaffold = join(target, '.claudinite/shared/packs/claudinite-tasks/converge-workflows.mjs');
115	if (declaresTasks && existsSync(scaffold)) {
116	  const { convergeWorkflows, stubsDir, declaredSecrets } = await import(pathToFileURL(scaffold).href);
117	  const stubs = stubsDir(target);
118	  const stubPath = join(stubs, 'claudinite-scheduler.yml');
119	  if (!existsSync(stubPath)) fail(`vendored stub not found at ${stubPath}`);
120	  const executorPath = join(stubs, 'claudinite-executor.yml');
121	  const { changed } = convergeWorkflows(target, fullName, {
122	    schedulerStub: readFileSync(stubPath, 'utf8'),
123	    executorStub: existsSync(executorPath) ? readFileSync(executorPath, 'utf8') : null,
124	    secretNames: await declaredSecrets(target, config),
125	    dailyHour: config?.taskScheduler?.dailyHour,
126	  });
127	  console.log(changed.length ? `bootstrap: workflows — ${changed.join(', ')}` : 'bootstrap: workflows: already scaffolded');
128	} else {
129	  console.log('bootstrap: claudinite-tasks is not declared — this repo runs no scheduled work, so no workflows');
130	}
131	
132	// 5. A place both sweeps deterministically run at each change (bootstrap.md's
133	// test/CI part). Seeded only when NO workflow runs the world sweep — a repo with
134	// its own CI keeps it, and adds the two steps there instead (reported below).
135	// One-time seed: the repo owns the file from here.
136	const CI_WORKFLOW = '.github/workflows/claudinite-ci.yml';
137	const workflowsDir = join(target, '.github', 'workflows');
138	const sweepWired = existsSync(workflowsDir) && readdirSync(workflowsDir)
139	  .some((f) => /\.ya?ml$/.test(f) && readFileSync(join(workflowsDir, f), 'utf8').includes('check_the_world.mjs'));
140	if (!sweepWired) {
141	  // The directory may not exist at all: a repo that declares no tasks pack was
142	  // scaffolded no workflow above, and this is the first file to land there.
143	  mkdirSync(workflowsDir, { recursive: true });
144	  writeFileSync(join(target, CI_WORKFLOW), `name: CI
145	on:
146	  pull_request:
147	  push:
148	    branches: [main]
149	  workflow_dispatch:
150	jobs:
151	  claudinite-sweeps:
152	    runs-on: ubuntu-latest
153	    steps:
154	      - uses: actions/checkout@v4
155	        with:
156	          fetch-depth: 0
157	          ref: \${{ github.event.pull_request.head.sha || github.sha }}
158	      - uses: actions/setup-node@v4
159	        with:
160	          node-version: 20
161	      - name: Conformance sweep (world scope)
162	        run: node .claudinite/shared/engine/checks/check_the_world.mjs
163	      - name: Conformance sweep (work scope)
164	        run: node .claudinite/shared/engine/checks/ci-work-scope.mjs --branch "\${{ github.head_ref || github.ref_name }}"
165	`);
166	  console.log(`bootstrap: seeded ${CI_WORKFLOW}`);
167	} else if (!existsSync(join(target, CI_WORKFLOW))) {
168	  console.log('bootstrap: a workflow already runs the world sweep — add the work sweep beside it if missing (bootstrap.md, the CI part)');
169	}
170	
171	// 6. Stage what this run wrote, so the sweep below judges tracked content and the
172	// adoption commit is one `git commit` away. Only the surfaces bootstrap owns —
173	// never `-A`, which would sweep up whatever else the checkout holds.
174	try {
175	  const paths = ['.gitignore', '.gitattributes', '.claudinite-settings.json', '.claudinite', '.claude/settings.json', '.github/workflows', 'CLAUDE.md', 'README.md']
176	    .filter((p) => existsSync(join(target, p)));
177	  execFileSync('git', ['add', '--', ...paths], { cwd: target, stdio: ['ignore', 'pipe', 'pipe'] });
178	  console.log(`bootstrap: staged ${paths.join(', ')}`);
179	} catch { console.log('bootstrap: not a git checkout — staging skipped'); }
180	
181	// 7. Gate and report. The self-test failing is genuine breakage (exit 1); world
182	// findings on an existing codebase are the expected backlog (bootstrap.md) and
183	// are reported, not fatal.
184	const selftest = runSelfTest(target);
185	console.log(selftest.ok ? 'selftest: ok' : `selftest: FAILED\n${selftest.output}`);
186	let sweep = { status: 0, output: '' };
187	try {
188	  sweep.output = execFileSync(process.execPath, [join(target, '.claudinite/shared/engine/checks/check_the_world.mjs'), '--root', target],
189	    { encoding: 'utf8', cwd: target, stdio: ['ignore', 'pipe', 'pipe'] });
190	} catch (e) { sweep = { status: e.status ?? 1, output: `${e.stdout ?? ''}${e.stderr ?? ''}` }; }
191	console.log(sweep.status === 0 ? 'world sweep: green' : `world sweep: findings to clear or accept before landing —\n${sweep.output.trim()}`);
192	
193	const pending = unansweredQuestions(packs, decl.packs);
194	if (pending.length) {
195	  console.log(`\nPENDING ADOPTION QUESTIONS (${pending.length}) — ask them ALL in ONE AskUserQuestion pass (batch up to 4 per call), then re-run this same command with an --answer per reply:`);
196	  for (const p of pending) {
197	    console.log(`  ${p.pack}/${p.question}: ${p.prompt}`);
198	    const distill = byId.get(p.pack)?.questions?.find((q) => q.id === p.question)?.distill;
199	    if (distill) console.log(`    distill: ${distill}`);
200	  }
201	}
202	// Core's own hand-over, printed in every adoption beside the packs'. It is core's
203	// because the scheduler and the executor are engine, not a pack — and without it
204	// the block only ever printed for the few packs that declare one, so the steps a
205	// human genuinely has to take left the flow as a line in a PR body (#1167).
206	const CORE_HANDOVER = [{
207	  pack: 'core',
208	  step: 'Finish the `Claudinite executor - <repo>` routine in the routines UI (its own prompt carries the SETUP block: model, and this repo as its only source and outcome), mint its API token there, and set it as this repo Actions secret `CCR_ROUTINE_TOKEN` (Settings → Secrets and variables → Actions).',
209	  breaks: 'every agentful work item converges to needs-human with a hand-off naming the unset secret; agentless tasks keep running',
210	  done: 'a scheduler run dispatches an agentful item and a session starts for it',
211	}];
212	const handover = [...CORE_HANDOVER, ...decl.packs.flatMap((e) => (byId.get(packEntryId(e))?.adoptionHandover ?? []).map((s) => ({ pack: packEntryId(e), ...s })))];
213	if (handover.length) {
214	  console.log(`\nHANDOVER — ${handover.length} step(s) only a human can do; file them as ONE issue, a checkbox each, never a note in the PR body:`);
215	  for (const h of handover) {
216	    console.log(`  [ ] (${h.pack}) ${h.step}`);
217	    if (h.breaks) console.log(`        while off: ${h.breaks}`);
218	    if (h.done) console.log(`        done when: ${h.done}`);
219	  }
220	}
221	console.log(`\nNEXT: ${pending.length ? 'interview → re-run → ' : ''}create the executor routine and write its endpoint into taskScheduler (bootstrap.md Part 6 — THIS session's work wherever the trigger tool is present, and before the commit so it lands in one PR), then commit (reference the adoption issue — create it BEFORE committing), push, PR. Once it lands: capture this session — Claudinite was not loaded when it started, so no SessionEnd hook will — with \`node .claudinite/shared/packs/claudinite-growth/capture-log.mjs --issue <adoption-issue>\`, and file the HANDOVER issue.`);
222	if (!selftest.ok) process.exit(1);
223

