1	import { test } from 'node:test';
2	import assert from 'node:assert/strict';
3	import { mkdtempSync, writeFileSync, existsSync, readFileSync } from 'node:fs';
4	import { execFileSync } from 'node:child_process';
5	import { tmpdir } from 'node:os';
6	import { join, dirname } from 'node:path';
7	import { fileURLToPath } from 'node:url';
8	import { hashedCron } from '../packs/claudinite-tasks/hash-minute.mjs';
9	import { packIdForRepo } from '../engine/converge-wiring.mjs';
10	
11	// Integration suite for bootstrap.mjs, THE one-shot adoption orchestrator: it runs
12	// the real canon (this checkout) against a fresh fixture repo, because the whole
13	// point of the script is that a fresh adoption needs nothing but this invocation —
14	// a hermetic mini-canon would prove the plumbing while missing exactly the
15	// cross-module wiring (vendor set → converge-wiring → sweeps) the script exists
16	// to sequence. It lives in engine-tests/ with the canon's other top-level-folder
17	// tests: ci.yml's test roots don't cover the repo root, where bootstrap.mjs sits
18	// beside its doc.
19	const CANON = dirname(dirname(fileURLToPath(import.meta.url)));
20	const BOOTSTRAP = join(CANON, 'bootstrap.mjs');
21	const REPO = 'acme/WidgetWorks';
22	const LOCAL_PACK_ID = packIdForRepo(REPO);
23	
24	const run = (root, ...args) => execFileSync(process.execPath, [BOOTSTRAP, '--target', root, '--repo', REPO, ...args],
25	  { encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'] });
26	
27	// A fresh consumer: a git repo with one committed README and nothing else —
28	// the state bootstrap.md's Part 1 meets. The README's exact text is a constant
29	// because a case below asserts bootstrap gave it back unchanged.
30	const FIXTURE_README = '# WidgetWorks\n\nA fixture.\n';
31	function freshRepo() {
32	  const root = mkdtempSync(join(tmpdir(), 'claudinite-bootstrap-'));
33	  const git = (...a) => execFileSync('git', a, { cwd: root, stdio: ['ignore', 'pipe', 'pipe'] });
34	  git('init', '-q');
35	  git('config', 'user.email', 'test@example.invalid');
36	  git('config', 'user.name', 'test');
37	  writeFileSync(join(root, 'README.md'), FIXTURE_README);
38	  git('add', '-A');
39	  git('commit', '-qm', 'seed');
40	  return root;
41	}
42	
43	const json = (root) => JSON.parse(readFileSync(join(root, '.claudinite-settings.json'), 'utf8'));
44	const at = (root, rel) => readFileSync(join(root, rel), 'utf8');
45	
46	test('bootstrap converges a fresh repo in one invocation', () => {
47	  const root = freshRepo();
48	  const out = run(root, '--packs', 'product-wiki', '--answer', 'product-wiki/product=A widget catalog app');
49	
50	  // Declaration: seeded defaults plus the requested pack, its answer recorded,
51	  // the scheduler anchors, and the vendor stamp.
52	  const decl = json(root);
53	  const ids = decl.packs.map((p) => (typeof p === 'string' ? p : p.id));
54	  assert.ok(ids.includes('basics'), `basics seeded (got ${ids.join(', ')})`);
55	  assert.ok(ids.includes('product-wiki'), 'requested pack declared');
56	  const wiki = decl.packs.find((p) => p?.id === 'product-wiki');
57	  assert.equal(wiki.answers.product, 'A widget catalog app');
58	  assert.deepEqual(decl.taskScheduler, { dailyHour: 4, weeklyDay: 'Sun', monthlyDay: 1 });
59	  assert.equal(decl.dailyClaudiniteUpdatesRequirePrReview, undefined,
60	    'the delivery override is written only by a repo that wants review (#1252)');
61	  assert.ok(decl.engineVersion, 'stamped');
62	  assert.ok(wiki.version, 'the requested pack is stamped on its own entry');
63	
64	  // The mount.
65	  assert.ok(existsSync(join(root, '.claudinite/shared/engine/checks/check_the_world.mjs')));
66	  assert.ok(existsSync(join(root, '.claudinite/shared/packs/product-wiki/RULES.md')));
67	
68	  // The wiring: hooks, ignore lines, both workflows (scheduler at the repo's
69	  // hashed minute), the rules index and its CLAUDE.md import, the seeded local
70	  // pack.
71	  const settings = at(root, '.claude/settings.json');
72	  for (const hook of ['session-start-command.sh', 'stop-command.mjs', 'pretooluse-command.mjs', 'session-end-command.mjs']) {
73	    assert.ok(settings.includes(hook), `${hook} registered`);
74	  }
75	  const ignore = at(root, '.gitignore');
76	  assert.ok(ignore.includes('/.claudinite-hooks.log\n') && ignore.includes('/.claudinite-hooks.log.tmp'));
77	  assert.ok(at(root, '.github/workflows/claudinite-scheduler.yml').includes(`cron: '${hashedCron(REPO)}'`));
78	  assert.ok(existsSync(join(root, '.github/workflows/claudinite-executor.yml')));
79	  assert.ok(existsSync(join(root, '.claudinite/claudinite-rules.GENERATED.md')));
80	  assert.ok(at(root, 'CLAUDE.md').includes('claudinite-rules.GENERATED.md'));
81	  assert.ok(existsSync(join(root, `.claudinite/local/packs/${LOCAL_PACK_ID}/pack.mjs`)));
82	  assert.equal(at(root, 'README.md'), FIXTURE_README, "the repo's README is not bootstrap's to write");
83	
84	  // A repo with no CI gets the minimal sweeps workflow.
85	  const ci = at(root, '.github/workflows/claudinite-ci.yml');
86	  assert.ok(ci.includes('check_the_world.mjs') && ci.includes('ci-work-scope.mjs'));
87	
88	  // The report: answered questions are settled, unanswered ones surface once,
89	  // batched for a single interview pass — never one popup per pack.
90	  assert.ok(!/PENDING.*\n(.|\n)*product-wiki\/product:/.test(out), 'answered question not re-asked');
91	  assert.ok(out.includes('product-wiki/users'), 'unanswered question listed');
92	  assert.ok(out.includes('product-wiki/market'), 'unanswered question listed');
93	  assert.ok(/selftest: ok/.test(out), `selftest ran green in:\n${out}`);
94	
95	  // The adoption session starts with no Claudinite loaded, so no SessionEnd hook
96	  // captures it — the report must tell the session to run the capture itself.
97	  assert.ok(out.includes('capture-log.mjs --issue'), `report names the conversation capture in:\n${out}`);
98	});
99	
100	test('bootstrap re-run is idempotent and records late answers', () => {
101	  const root = freshRepo();
102	  run(root, '--packs', 'product-wiki');
103	
104	  const before = json(root);
105	  const out = run(root, '--answer', 'product-wiki/users=Widget shoppers');
106	  const after = json(root);
107	
108	  const wiki = after.packs.find((p) => p?.id === 'product-wiki');
109	  assert.equal(wiki.answers.users, 'Widget shoppers');
110	  // Nothing but the new answer (which upgrades the string entry to an object)
111	  // and the refreshed stamp moves.
112	  before.packs = before.packs.map((p) => (p === 'product-wiki' || p?.id === 'product-wiki' ? wiki : p));
113	  before.engineVersion = after.engineVersion;
114	  assert.deepEqual(after, before);
115	  assert.ok(/wiring: already converged/.test(out), `second run reports converged:\n${out}`);
116	});
117	
118	test('bootstrap refuses an answer that names no question', () => {
119	  const root = freshRepo();
120	  assert.throws(
121	    () => run(root, '--packs', 'product-wiki', '--answer', 'product-wiki/nope=x'),
122	    (e) => e.status === 1 && /nope/.test(`${e.stdout}${e.stderr}`),
123	  );
124	});
125	
126	// The hand-over block, and what it must never depend on. Before #1167 it was
127	// assembled from `adoptionHandover` on the DECLARED packs alone, so a repo whose
128	// packs happen to declare none printed nothing — and the two steps every adoption
129	// actually leaves a human (the executor's token, the web environment's Setup
