514	  const record = (pack, from, to) => ({
515	    id: `test-${pack}`,
516	    dir: `packs/${pack}/migrations/test-shared-workflow`,
517	    rewrite: [{ file: EXECUTOR_WORKFLOW, replace: [{ from, to }] }],
518	    applyStage: { why: 'a workflow file was withheld and needs delivering' },
519	  });
520	  const r = await packUpdate(root, {
521	    fullName: 'o/r',
522	    selfTestRun: () => 'ok',
523	    extraRecords: [
524	      // Both read the LIVE file — the first one's write went to staging, not to the
525	      // destination — so both match the same anchor and the second's content wins.
526	      record('claudinite-tasks', '# MARKER', '# FIRST'),
527	      record('claudinite-lifecycle', '# MARKER', '# SECOND'),
528	    ],
