1	// Fresh-path wiring convergence (task-code-work DESIGN §7, the primitive absorbed from
2	// #405). The deterministic half of the self-refresh that has nothing to do with the
3	// vendored mount's CONTENT: the repo-specific wiring EVERY Claudinite member carries,
4	// converged idempotently in code so the nightly refresh never needs a model to re-enact
5	// bootstrap's prose.
6	//
7	// DISTRIBUTION WIRING ONLY. What a member needs in order to receive and load pack
8	// content — the settings hooks, the rules index and the CLAUDE.md import that loads it,
9	// the mount's git attributes, the repo's own local pack. Scheduling
10	// wiring is not here: the two workflow files belong to the mechanism that runs them and
11	// are scaffolded at adoption by the tasks pack (#1317), so a member without that pack
12	// converges exactly this and nothing about a queue it does not have.
13	//
14	// One source of truth: bootstrap Part 5 describes this same set for a fresh adoption;
15	// this module is what both bootstrap and the update flows CALL, so the wiring can never
16	// drift between "how a repo is set up" and "how the nightly keeps it set up".
17	//
18	// Operates on a repo working tree at `root` with node:fs directly (like
19	// apply-vendor-set.mjs), returning a summary of what it changed — idempotent: a
20	// repo already converged produces an empty change list.
21	
22	import { existsSync, readFileSync, writeFileSync, mkdirSync, rmSync } from 'node:fs';
23	import { join, dirname, relative, sep } from 'node:path';
24	import { pathToFileURL } from 'node:url';
25	import { writeRulesIndex, RULES_INDEX_FILE, RULES_INDEX_IMPORT } from './pack_loader/generate-rules-index.mjs';
26	import { writeSkillsIndex, SKILLS_INDEX_FILE } from './pack_loader/generate-skills-index.mjs';
27	import { LOCAL_PACKS_SUBDIR, LOCAL_DECL_PREFIX, SHARED_SUBDIR } from './pack_loader/pack-registry.mjs';
28	
29	// The mount's two halves as git wants them spelled: '/' separators, and the shared
30	// subtree's own name for a pattern written from inside the mount root. SHARED_SUBDIR
31	// is joined with the platform's separator.
32	const MOUNT_ROOT = dirname(SHARED_SUBDIR).split(sep).join('/');
33	const SHARED_NAME = SHARED_SUBDIR.split(sep).pop();
34	import { settingsPath } from './settings-file.mjs';
35	import { ENDPOINTS_KEY, LEGACY_ENDPOINTS_KEY } from './checks/helpers/repo-context.mjs';
36	
37	// The settings-hook registrations a scheduled repo carries (bootstrap Part 5).
38	// Ensured present without clobbering — a set-union keyed on the command string, so
39	// a repo's own extra hooks and any hand-added entries survive untouched.
40	// The PreToolUse guard watches EVERY tool: an active pack's action declaration
41	// (guardToolCalls) may name any of them, and the guard fast-exits on a call no
42	// declaration names (engine/hooks/pretooluse-command.mjs).
43	export const PRETOOLUSE_MATCHER = '.*';
44	
45	export const REQUIRED_HOOKS = [
46	  { event: 'SessionStart', matcher: null, command: 'bash $CLAUDE_PROJECT_DIR/.claudinite/shared/engine/hooks/session-start-command.sh' },
47	  { event: 'Stop', matcher: null, command: 'node $CLAUDE_PROJECT_DIR/.claudinite/shared/engine/hooks/stop-command.mjs' },
48	  { event: 'PreToolUse', matcher: PRETOOLUSE_MATCHER, command: 'node $CLAUDE_PROJECT_DIR/.claudinite/shared/engine/hooks/pretooluse-command.mjs' },
49	  { event: 'SessionEnd', matcher: null, command: 'node $CLAUDE_PROJECT_DIR/.claudinite/shared/engine/hooks/session-end-command.mjs' },
50	  // The two trigger hooks (engine/pack_loader/path-scoped-skills.mjs): an owner
51	  // prompt or a tool result a skill forces itself for gets the load instruction
52	  // injected at that moment. PostToolUse, like PreToolUse, watches every tool.
53	  { event: 'UserPromptSubmit', matcher: null, command: 'node $CLAUDE_PROJECT_DIR/.claudinite/shared/engine/hooks/user-prompt-submit-command.mjs' },
54	  { event: 'PostToolUse', matcher: '.*', command: 'node $CLAUDE_PROJECT_DIR/.claudinite/shared/engine/hooks/post-tool-use-command.mjs' },
55	];
56	
57	export const SETTINGS_PATH = '.claude/settings.json';
58	export const CLAUDE_MD = 'CLAUDE.md';
59	
60	// The retired corpus-index import (#385): a line importing `.claudinite/shared/CLAUDE.md`.
61	// The whole line (and its trailing newline) is removed wherever it appears.
62	const CORPUS_IMPORT_RE = /^.*@\.claudinite\/shared\/CLAUDE\.md.*\n?/m;
63	
64	// The project's settings, loaded through the one reader that validates them.
65	// Dynamic and in one place: the scheduler reaches the checks helpers exactly here,
66	// so the cross-tree import stays a single, reviewable edge.
67	const repoConfig = async (root) => (await import('./checks/helpers/repo-context.mjs')).loadConfig(root);
68	
69	// Re-converge the scheduler workflow to the vendored stub, with the cron minute set
70	// to this repo's stable hashed value (never guessed — hash-minute.mjs, a pure
71	// function of the full name, so re-vendors and this convergence agree) and the
72	// `stubText` is the vendored stub's content (the caller reads it from the mount).
73	// Returns true when the file was written (absent, or drifted from the target).
74	// What this repo's scheduler workflow SHOULD contain — the stub with its cron
75	// resolved, as text, touching no disk.
76	//
77	// A workflow is now a pure function of its stub. Secrets used to be stamped in here
78	// by name, which made these files a function of the TASK SET and is what wedged a
79	// member in #1296. They are stamped by the tasks pack's converge-workflows.mjs, at
80	// the `# claudinite:secrets` marker in its executor stub (#1336).
81	//
82	// Split out from the converge below because the pack update flow needs the answer
83	// without the side effect: it cannot write this file (its caller pushes with the
84	// Action's GITHUB_TOKEN, which GitHub never lets near `.github/workflows/`), so it
85	// WITHHOLDS the content and hands it to a lane that can. A flow that had to write
86	// the file in order to learn what it should say could not do that.
87	// Ensure the required settings hooks are present (add-if-missing, never clobber).
88	// Returns { added: [labels], error? }. A malformed settings file is reported, never
89	// overwritten (the transactional stance — surface it, don't destroy hand config).
90	export function ensureHooks(root) {
91	  const path = join(root, SETTINGS_PATH);
92	  let settings = {};
93	  if (existsSync(path)) {
94	    try { settings = JSON.parse(readFileSync(path, 'utf8')); }
95	    catch { return { added: [], error: `${SETTINGS_PATH} is not valid JSON — left untouched` }; }
96	  }
97	  settings.hooks ??= {};
98	  const added = [];
99	  for (const h of REQUIRED_HOOKS) {
100	    const list = (settings.hooks[h.event] ??= []);
101	    const ours = (group) => (group.hooks ?? []).some((entry) => entry?.command === h.command);
102	    const present = list.some((group) => (h.matcher == null || group.matcher === h.matcher) && ours(group));
103	    // The command is the registration's identity: a group already running it under
104	    // an earlier matcher is retargeted, never joined by a second group that would
105	    // run the same guard twice on the tools both matchers name.
106	    const retarget = present ? null : list.find((group) => h.matcher != null && ours(group) && group.matcher !== h.matcher);
107	    if (retarget) {
108	      retarget.matcher = h.matcher;
109	      added.push(`${h.event}[${h.matcher}]`);
110	    } else if (!present) {
111	      list.push({ ...(h.matcher != null ? { matcher: h.matcher } : {}), hooks: [{ type: 'command', command: h.command }] });
112	      added.push(`${h.event}${h.matcher ? `[${h.matcher}]` : ''}`);
113	    }
114	  }
115	  if (added.length) {
116	    mkdirSync(dirname(path), { recursive: true });
117	    writeFileSync(path, JSON.stringify(settings, null, 2) + '\n');
118	  }
119	  return { added };
120	}
121	
122	// Remove the retired `@.claudinite/shared/CLAUDE.md` corpus-index import (#385) from
123	// the repo's CLAUDE.md. Returns true when a line was removed.
124	export function removeRetiredCorpusImport(root) {
125	  const path = join(root, CLAUDE_MD);
126	  if (!existsSync(path)) return false;
127	  const text = readFileSync(path, 'utf8');
128	  if (!CORPUS_IMPORT_RE.test(text)) return false;
129	  writeFileSync(path, text.replace(CORPUS_IMPORT_RE, ''));
130	  return true;
131	}
132	
133	// The CLAUDE.md channel (#807): the generated rules index, plus the one line in the
134	// repo's own CLAUDE.md that imports it. Converged here rather than left to a session
135	// because the index is a function of the DECLARATION — so the two flows that already
136	// change a declaration (the nightly engine refresh and any pack change) are exactly
137	// the moments it can go stale, and both call convergeWiring.
138	//
139	// NOT the retired `@.claudinite/shared/CLAUDE.md` this file still strips above. That
140	// import reached INTO the mount, which is one-directional and slated to become a
141	// submodule; this one names a consumer-owned file sitting BESIDE it, derived from the
142	// consumer's own declaration. The two coexist deliberately: a member converging today
143	// loses the old shape and gains the new one in the same pass.
144	//
145	// The import goes after the first `# ` heading when the repo has one — a repo's title
146	// stays its first line — and at the very top otherwise. A repo with no CLAUDE.md at all gets one: without it the
147	// index is a file nothing loads.
148	const RULES_INDEX_IMPORT_RE = new RegExp(`^\\s*${RULES_INDEX_IMPORT.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}\\s*$`, 'm');
149	
150	export function ensureRulesIndexImport(root) {
151	  const path = join(root, CLAUDE_MD);
152	  if (!existsSync(path)) {
153	    writeFileSync(path, `${RULES_INDEX_IMPORT}\n`);
154	    return true;
155	  }
156	  const text = readFileSync(path, 'utf8');
157	  if (RULES_INDEX_IMPORT_RE.test(text)) return false;
158	  const lines = text.split('\n');
159	  const title = lines.findIndex((l) => l.startsWith('# '));
160	  const at = title === -1 ? 0 : title + 1;
161	  lines.splice(at, 0, ...(at === 0 ? [RULES_INDEX_IMPORT, ''] : ['', RULES_INDEX_IMPORT]));
162	  writeFileSync(path, lines.join('\n'));
163	  return true;
164	}
165	
166	// --- the mount's own git attributes -----------------------------------------
167	
168	// Everything Claudinite asks git to know about is a file INSIDE the mount root, so
169	// the attributes file lives there and a member's root `.gitattributes` stays the
170	// repo's own: git reads a `.gitattributes` in any directory, and its patterns are
171	// relative to that directory. Claudinite-owned, so it is converged to exact content
172	// rather than appended to.
173	export const MOUNT_ATTRIBUTES_FILE = `${MOUNT_ROOT}/.gitattributes`;
174	
175	// `*GENERATED*` covers every generated file the mount carries — the rules and skills
176	// indexes, the usage fold — under the canon's GENERATED-file discipline and the
177	// `generated-merge-driver` check that enforces it, so a conflicting merge auto-resolves
178	// and this file never grows a line per artifact.
179	//
180	// The shared subtree is canon-owned content the member never authored, so the git HOST
181	// is told so: Linguist keeps a member's language stats off the corpus (which outweighs
182	// a small member's own source by byte count) and collapses the mount in a converge
183	// diff. Presentation only — the CHECK-scope exclusion is a separate, structural rule
184	// in the file-set builder (engine/checks/helpers/repo-context.mjs), which drops the
185	// mount prefix before attributes are ever consulted, so that exclusion holds on a host
186	// and a checkout that honor no attributes at all.
187	const MOUNT_ATTRIBUTES_TEXT = [
188	  '# GENERATED by Claudinite (engine/converge-wiring.mjs) — the attributes of the',
189	  "# mount's own files. A repo's root .gitattributes is the repo's own.",
190	  '*GENERATED* merge=ours',
191	  `${SHARED_NAME}/** linguist-vendored`,
192	].join('\n') + '\n';
193	
194	// Returns true when the file was written (absent, or drifted from the target).
195	export function ensureMountAttributes(root) {
196	  const path = join(root, MOUNT_ATTRIBUTES_FILE);
197	  if (existsSync(path) && readFileSync(path, 'utf8') === MOUNT_ATTRIBUTES_TEXT) return false;
198	  mkdirSync(dirname(path), { recursive: true });
199	  writeFileSync(path, MOUNT_ATTRIBUTES_TEXT);
200	  return true;
201	}
202	
203	// The three names the wiring used to expose, one per line it appended to the member's
204	// root file. Kept, and pointed at the file that now carries all three, because a
205	// member spends a window holding a NEWER engine beside an OLDER pack: a vendored
206	// pack-update flow still imports the first of these by name, and a removed export is
207	// a link-time SyntaxError that faults the whole flow.
208	/** @deprecated call ensureMountAttributes — the three lines are one converged file. */
209	export const ensureRulesIndexMergeAttribute = ensureMountAttributes;
210	/** @deprecated call ensureMountAttributes. */
211	export const ensureSkillsIndexMergeAttribute = ensureMountAttributes;
212	/** @deprecated call ensureMountAttributes. */
213	export const ensureMountVendoredAttribute = ensureMountAttributes;
214	
215	// What those three appended, plus the `merge=ours` line the tasks pack seeded for the
216	// usage fold — the whole set Claudinite ever planted in a member's ROOT file, taken
217	// back now that the mount has its own (#1748). Each is matched as a whole line, so a
218	// repo's own entry for one of these paths (spelled differently, or carrying other
219	// attributes) is left alone; a root file with nothing but these in it goes away,
220	// leaving a repo that never had one as it was.
221	const RETIRED_ROOT_ATTRIBUTES = [
222	  'claudinite-rules.GENERATED.md merge=ours',
223	  'claudinite-skills.GENERATED.md merge=ours',
224	  'usage.GENERATED.json merge=ours',
225	  `${SHARED_SUBDIR.split(sep).join('/')}/** linguist-vendored`,
226	];
227	
228	export function removeRetiredRootAttributes(root) {
229	  const path = join(root, '.gitattributes');
230	  if (!existsSync(path)) return false;
231	  const text = readFileSync(path, 'utf8');
232	  const kept = text.split('\n').filter((line) => !RETIRED_ROOT_ATTRIBUTES.includes(line.trim()));
233	  const next = kept.join('\n');
234	  if (next === text) return false;
235	  if (next.trim() === '') rmSync(path);
236	  else writeFileSync(path, next);
237	  return true;
238	}
239	
240	// --- the repo's own local pack, seeded once at adoption ----------------------
241	
242	// Every repo has lessons that are its own and portable nowhere: they need a home the
243	// moment there is anything to write, and a session that has to invent one first
244	// usually doesn't — it writes the rule into `basics` or into a `CLAUDE.md` paragraph
245	// instead, which is how a project's rules end up somewhere the corpus cannot reach.
246	// So adoption seeds the home empty, named for the repo, declared and imported like any
247	// other pack.
248	//
249	// BOOTSTRAP ONLY: this is a one-time seed of a file the repo then OWNS. A nightly that re-created it would resurrect a
250	// pack the owner deliberately deleted, and a nightly that rewrote it would overwrite
251	// the rules it exists to hold.
252	
253	// A repo name as a pack id: kebab-case, the canon's naming rule for a pack directory
254	// (lowercase words joined by single hyphens), since the id is what the declaration,
255	// the mount path and every cross-reference then spell.
256	export const packIdForRepo = (fullName) => (fullName ?? '').split('/').pop()
257	  .replace(/([a-z0-9])([A-Z])/g, '$1-$2')
258	  .replace(/[^a-zA-Z0-9]+/g, '-')
259	  .toLowerCase()
260	  .replace(/^-+|-+$/g, '');
261	
262	const SEED_MANIFEST = (id) => `// ${id} — this repo's own pack: everything local, and portable nowhere. Its rules,
263	// and the checks, skills and tasks that carry them, all live here.
264	// Seeded empty at adoption; everything in it is this repo's to write. A lesson that
265	// would hold in another repo belongs in a canon pack instead — propose it upstream.
266	//
267	// The id is this directory's name and the prose is the RULES.md beside this file —
268	// both by convention (engine/pack_loader/pack-conventions.mjs), so neither is
269	// declared here.
270	export default {
271	  version: 1,
272	  ruleRoutingGuidance: {
273	    belongs: 'everything specific to this repository and portable nowhere else: its working rules, and the checks, skills and tasks carrying them',
274	    excludes: 'anything true beyond this repo — that belongs in a canon pack, proposed upstream',
275	  },
276	  detect: null,
277	  marker: null,
278	  worldRules: [],
279	};
280	`;
281	
282	const SEED_PROSE = (id) => `# ${id} — this repo's own pack
283	
284	The home for everything **specific to this repository**: the rules below, and beside them the
285	checks, skills and tasks that carry them. Nothing local needs a home invented for it — this is
286	that home. This file is loaded into every session through the rules index, so what lands *here*
287	should be a directive an agent can act on, not a description of how something works; a rule a
288	deterministic check can enforce belongs in this pack's \`declared-checks.json\` instead, and a
289	procedure with a nameable trigger in its own \`skills/<name>/SKILL.md\`.
290	
291	A lesson that would hold in another repo does not belong here — propose it to the Claudinite
292	canon instead, where every repo gets it.
293	
294	<!-- Nothing yet. The growth lifecycle writes here; so may you. -->
295	`;
296	
297	// Seed `.claudinite/local/packs/<repo>/` and declare it. Returns the pack id when it
298	// created one, null when the repo already has that pack or already declares any local
299	// pack — a repo that has grown its own home must never get a second, empty one.
300	export function seedRepoLocalPack(root, fullName) {
301	  const id = packIdForRepo(fullName);
302	  if (!id) return null;
303	  const dir = join(root, LOCAL_PACKS_SUBDIR, id);
304	  if (existsSync(dir)) return null;
305	
306	  const settingsFile = settingsPath(root);
307	  let raw;
308	  try { raw = JSON.parse(readFileSync(settingsFile, 'utf8')); } catch { return null; }
309	  const declared = Array.isArray(raw.packs) ? raw.packs : [];
310	  // Any local declaration at all means this repo already has a home of its own.
311	  if (declared.some((p) => String(typeof p === 'string' ? p : p?.id).startsWith('local'))) return null;
312	
313	  mkdirSync(dir, { recursive: true });
314	  writeFileSync(join(dir, 'pack.mjs'), SEED_MANIFEST(id));
315	  writeFileSync(join(dir, 'RULES.md'), SEED_PROSE(id));
316	
317	  // Declared as text, never a JSON round-trip: re-serializing rewrites what it was not
318	  // asked to — `ensure_ascii` escapes every non-ASCII character in a settings file full
319	  // of prose, and indent and key order become the serializer's opinion.
320	  const text = readFileSync(settingsFile, 'utf8');
321	  const entry = `"${LOCAL_DECL_PREFIX}${id}"`;
322	  const patched = text.replace(/("packs"\s*:\s*\[)/, (m) => `${m}\n    ${entry},`);
323	  writeFileSync(settingsFile, patched === text
324	    ? text // no `packs` array to extend — leave the file alone rather than guess at its shape
325	    : patched);
326	  return id;
327	}
328	
329	// Strip the retired `badges` setting from the settings file — it configured a README
330	// row nothing writes any more (#1750). `badges` is
331	// not in CONFIG_KEYS, so a member still carrying it gets an unknown-setting error
332	// until the key goes; doing it here — beside the retired corpus import, for the
333	// same reason — means the converge that already runs on every member clears it,
334	// and nobody hand-edits a settings file to satisfy a check.
335	// Returns true when the key was removed. A malformed settings file is left alone.
336	//
337	// Cut out as TEXT, re-serializing only as a fallback: a JSON round-trip rewrites
338	// the whole file — re-escaping every non-ASCII character in the prose a settings
339	// file is full of — so a three-line deletion arrives as a diff touching every
340	// `reason` in the repo.
341	export function removeRetiredBadgeSetting(root) {
342	  const path = settingsPath(root);
343	  if (!existsSync(path)) return false;
344	  const text = readFileSync(path, 'utf8');
345	  let raw;
346	  try { raw = JSON.parse(text); } catch { return false; }
347	  if (raw === null || typeof raw !== 'object' || Array.isArray(raw) || raw.badges === undefined) return false;
348	  // The key as a materialized settings file carries it: two-space indent, either
349	  // followed by a comma (mid-object) or preceded by one (last key).
350	  const surgical = text.replace(/(,)?\n[ \t]*"badges"[ \t]*:[ \t]*\{[^{}]*\}(,)?(?=\n)/, (m, before, after) => (before && after ? ',' : ''));
351	  const next = surgical !== text && parses(surgical, raw) ? surgical
352	    : JSON.stringify(rest(raw), null, 2) + '\n';
353	  writeFileSync(path, next);
354	  return true;
355	}
356	
357	const rest = ({ badges, ...keep }) => keep;
358	// The surgical cut is only taken when it produces the settings the round-trip would
359	// have — never trust a regex against JSON without re-reading what it made.
360	const parses = (text, raw) => {
361	  try { return JSON.stringify(JSON.parse(text)) === JSON.stringify(rest(raw)); }
362	  catch { return false; }
363	};
364	
365	// Converge every wiring surface, returning a flat summary of what changed (empty
366	// when the repo was already converged). `stubText` is the vendored scheduler stub.
367	//
368	// `workflows: false` converges everything EXCEPT `.github/workflows/`. The engine
369	// update flow passes it: the scheduler workflow's content is a function of the
370	// task set, so pack changes are what rewrite it, and only the pack flow carries a
371	// credential that can land a workflow file at all (DESIGN §2.4, §3.7). A flow that
372	// wrote one it cannot deliver would fail its whole push, not just that file.
373	// `seedLocalPack` defaults off: it is a one-time seed of a file the repo then owns,
374	// and only bootstrap passes it — a nightly that re-created it would resurrect a pack
375	// the owner deliberately deleted.
376	export async function convergeWiring(root, fullName, { seedLocalPack = false } = {}) {
377	  const changed = [];
378	  const hooks = ensureHooks(root);
379	  for (const h of hooks.added) changed.push(`hook:${h}`);
380	  if (removeRetiredCorpusImport(root)) changed.push(`removed retired ${CLAUDE_MD} corpus import`);
381	  if (removeRetiredBadgeSetting(root)) changed.push('removed retired badges setting');
382	  // Adoption only, and BEFORE the index: seeding declares a pack, and the index is a
383	  // function of the declaration, so seeding after it would leave the repo's own pack
384	  // unimported until some later converge.
385	  if (seedLocalPack) {
386	    const seeded = seedRepoLocalPack(root, fullName);
387	    if (seeded) changed.push(`seeded ${LOCAL_PACKS_SUBDIR}/${seeded}`);
388	  }
389	  // The CLAUDE.md channel, in dependency order: the index, then the import that
390	  // loads it, then the merge attribute that keeps it from being hand-resolved.
391	  if (await writeRulesIndex(root)) changed.push(RULES_INDEX_FILE);
392	  if (await writeSkillsIndex(root)) changed.push(SKILLS_INDEX_FILE);
393	  if (ensureRulesIndexImport(root)) changed.push(`${CLAUDE_MD} rules-index import`);
394	  if (ensureMountAttributes(root)) changed.push(MOUNT_ATTRIBUTES_FILE);
395	  if (removeRetiredRootAttributes(root)) changed.push('removed retired root .gitattributes entries');
396	  return { changed, ...(hooks.error ? { error: hooks.error } : {}) };
397	}
398	
399	// CLI: `node converge-wiring.mjs [owner/repo] [--seed-local-pack]` —
400	// converge THIS repo's distribution wiring. The full name comes from argv or
401	// GITHUB_REPOSITORY/CLAUDINITE_REPO. This is the single surface bootstrap (Part 5) and
402	// the update flows both invoke, so the wiring set is defined once, here — and the flag
403	// is the whole difference between them: seeding the repo's own local pack is a ONE-TIME
404	// seed of a file the repo then owns, which is exactly why the nightly must not pass it
405	// — it would resurrect a pack the owner deliberately deleted. The two workflow files are the tasks pack's to scaffold, and its
406	// own converge-workflows.mjs is the command that does it.
407	async function main() {
408	  const argv = process.argv.slice(2);
409	  const seedLocalPack = argv.includes('--seed-local-pack');
410	  const fullName = argv.find((a) => !a.startsWith('--')) || process.env.GITHUB_REPOSITORY || process.env.CLAUDINITE_REPO;
411	  if (!fullName) { console.error('converge-wiring: need owner/repo (argv or GITHUB_REPOSITORY)'); process.exit(1); }
412	  const root = process.env.CLAUDINITE_REPO_ROOT || process.cwd();
413	  const { changed, error } = await convergeWiring(root, fullName, { seedLocalPack });
414	  if (error) console.log(`! ${error}`);
415	  console.log(changed.length ? `converge-wiring: ${changed.join(', ')}` : 'converge-wiring: already converged');
416	}
417	
418	if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) main();
