1	// The baselining REHEARSAL runner (#593 phase 2): build a fixture consumer in a
2	// temp dir, run the REAL converge against this canon checkout, and report what a
3	// member would be left with.
4	//
5	// "The real converge" is load-bearing. It invokes the same three scripts the
6	// nightly worker invokes, as subprocesses, in the same order:
7	//
8	//   vendoring/apply-vendor-set.mjs   the mount + stamp
9	//   engine/converge-wiring.mjs              hooks, rules index, mount gitattributes
10	//   engine/migrations/apply.mjs      the mechanical notes
11	//   vendoring/apply-vendor-set.mjs   again, when a note changed the DECLARATION (a
12	//                                    seeded pack's content is not in the first pass's
13	//                                    set — the worker does the same, conditionally)
14	//
15	// then asks the two questions that matter, in the order that matters:
16	//
17	//   engine/selftest.mjs      can Claudinite still RUN here?
18	//   check_the_world.mjs      and is the result conformant?
19	//
20	// Self-test first, because it is the one that catches a machinery break — and a
21	// broken machine reports no findings precisely because it is not running, so a
22	// content check consulted first would answer "green" and mean nothing.
23	//
24	// A rehearsal never touches the canon and never touches a real repo: everything
25	// happens under a temp dir that is removed afterwards.
26	
27	import { mkdtempSync, mkdirSync, writeFileSync, existsSync, readFileSync } from 'node:fs';
28	import { execFileSync } from 'node:child_process';
29	import { join, dirname } from 'node:path';
30	import { tmpdir } from 'node:os';
31	import { fileURLToPath } from 'node:url';
32	import { removeTree } from '../../engine/remove-tree.mjs';
33	import { settingsPath, isSettingsFile } from '../../engine/settings-file.mjs';
34	import { installedVersions, withInstalledVersions } from '../../engine/installed-versions.mjs';
35	
36	// The fixture's declaration with this mode's installed versions written in: the
37	// engine version at the top, and every declared pack pinned at the same number so
38	// each pack's own records select too. `installed: null` writes nothing, which is the
